"""Authored APS dossiers. Fictional evidence is distinct from legal references.

Rows describe deliberate comparisons, not extra waiting time. Answer keys are
kept server-side by public_practice. Stable source IDs preserve prior attempts.
"""
from __future__ import annotations

CASES = {}


def choice(prompt, good, alternatives, explanation, context=''):
    return dict(kind='single', prompt=prompt, texts=[good, *alternatives],
                explanation=explanation, context=context)


def classify(prompt, categories, rows, explanation):
    return dict(kind='classify', prompt=prompt, categories=categories, rows=rows, explanation=explanation)


def associate(prompt, pairs, explanation):
    return dict(kind='matching', prompt=prompt, pairs=pairs, explanation=explanation)


def sequence(prompt, steps, explanation):
    return dict(kind='order', prompt=prompt, steps=steps, explanation=explanation)


def dossier(key, title, teaching, documents, exercises):
    assert 'aps62-' + key not in CASES and len(documents) >= 3 and len(exercises) >= 5
    CASES['aps62-' + key] = dict(title=title, teaching=teaching,
        documents=[dict(title=title, text=text) for title, text in documents], exercises=exercises)


dossier('01-01', 'Une prestation qui déborde du contrat',
    "Une consigne précise comment accomplir une mission, mais ne crée pas un pouvoir légal. Pour analyser une demande, séparez l’activité autorisée, le lieu où elle est prévue et les moyens demandés. Un contrôle d’accès à un site ne devient pas un contrôle de police parce que le client emploie le mot sécurité. L’accueil lié à la surveillance ne se confond pas non plus avec toute prestation commerciale.\n\nL’exclusivité des activités de surveillance et de gardiennage oblige à examiner les tâches étrangères à leur objet. Un contrat ou une demande orale du client ne dispense jamais de cette vérification. L’agent transmet l’écart à son encadrement, assure les mesures qui restent dans sa mission et propose un relais adapté. Il ne qualifie pas seul une exception juridique. La qualité d’une décision se mesure aussi à ce qui a été maintenu pour protéger le site pendant la clarification.",
    [('Fiche de poste · centre logistique Boréal', 'De 06 h à 14 h : surveillance du portail privé, vérification des autorisations de livraison et alerte au poste central. Le trottoir et l’arrêt de bus sont hors du périmètre contractuel. Un agent de relève peut être demandé au chef de poste.'),
     ('Message du client à 07 h 20', 'Un véhicule gêne la sortie. Le client demande de relever l’identité de tous les passants sur le trottoir, de prendre les clés du conducteur et de décharger son camion pour gagner du temps. Il précise que ces tâches seront facturées avec la surveillance.'),
     ('Informations recueillies', 'Le portail reste praticable pour les secours. Aucun danger immédiat ni violence n’est constaté. Le conducteur est présent et accepte de déplacer son véhicule après une livraison. Le chef de poste est joignable par radio ; le service logistique peut prendre en charge le déchargement.')],
    [classify('Quelles demandes relèvent de la mission décrite ?', ['Dans la mission', 'À écarter et faire clarifier'],
        [('Vérifier les autorisations des livraisons au portail',0),('Contrôler l’identité de tous les passants sur le trottoir',1),('Décharger les marchandises comme prestation de surveillance',1),('Alerter le poste central sur la gêne constatée',0)],
        'Le périmètre, la finalité et les pouvoirs se vérifient séparément. Le contrat ne donne ni prérogative générale de contrôle d’identité ni droit de retenir des clés. Le déchargement relève ici de la logistique, sans lien avec la surveillance.'),
     associate('À qui rattacher chaque besoin dans ce dossier ?', [('Déplacer le véhicule volontairement','Conducteur'),('Prendre en charge les colis','Service logistique'),('Clarifier les tâches et organiser une relève','Chef de poste'),('Maintenir la surveillance du portail','Agent affecté')], 'Distribuer les rôles permet de traiter le problème sans abandonner le poste ni absorber les missions des autres services.'),
     choice('Le client confirme par écrit sa demande. Quel élément change ?', 'La demande est désormais traçable ; ses limites légales restent à vérifier.', ['L’écrit étend le droit de contrôler les passants.', 'L’écrit permet de conserver les clés jusqu’à la fin de la livraison.'], 'La preuve d’une instruction n’est pas la preuve de sa légalité. Conservez les faits utiles et sollicitez votre hiérarchie.'),
     sequence('Ordonnez le traitement de cette demande sans urgence immédiate.', ['Vérifier les faits et maintenir la surveillance du portail', 'Expliquer la limite de mission au client et saisir le chef de poste', 'Organiser le relais logistique confirmé', 'Tracer la demande, la décision et le relais obtenu'], 'Cette chronologie répond au cas décrit. Un danger immédiat imposerait d’abord une mise en sécurité et une alerte adaptées.'),
     choice('À 07 h 30, une personne chute devant le véhicule. Quelle évolution est déterminante ?', 'Une urgence de secours apparaît et doit être traitée sans s’exposer.', ['La chute autorise le contrôle de tous les passants.', 'Le désaccord contractuel doit être réglé avant tout appel.'], 'La protection d’une victime ne dépend pas de la résolution du litige contractuel. Alertez, protégez et suivez les consignes des secours dans vos compétences.')])

dossier('01-02', 'Trois pièces pour une prise de poste',
    "L’aptitude professionnelle, la décision administrative autorisant l’exercice et le badge de l’employeur ne remplissent pas la même fonction. La réussite à une formation ne démontre pas à elle seule qu’un titre est actuellement valide. Une vérification utile porte sur le titulaire, l’activité autorisée et la validité du droit d’exercer à la date de la mission.\n\nLes téléservices officiels du CNAPS servent à vérifier les titres dans le cadre prévu. Une capture ancienne, un numéro recopié ou l’assurance orale d’un collègue ne remplacent pas cette vérification. En cas d’écart, l’encadrement doit résoudre la situation avant l’affectation concernée. L’agent n’interprète pas lui-même un récépissé comme une autorisation pour toutes les activités ; il fait contrôler ce que le document permet réellement et pendant quelle période.",
    [('Dossier du remplaçant', 'Le remplaçant présente une attestation de réussite à la formation et un badge portant le logo de son employeur. Sa carte professionnelle mentionne un numéro de titre. Une capture du résultat de vérification date de six mois.'),
     ('Planning du jour', 'La mission est de la surveillance humaine non armée de 08 h à 18 h. Aucun exercice cynophile ni armé n’est prévu. Le client souhaite ouvrir à 08 h même si les vérifications administratives ne sont pas terminées.'),
     ('Contrôle par le responsable', 'À 07 h 45, le responsable relève une différence entre le nom du titulaire et celui du planning. Le salarié indique un changement récent d’état civil. Le service administratif peut examiner les justificatifs et procéder à la vérification officielle avant de confirmer l’affectation.')],
    [associate('Reliez chaque pièce à ce qu’elle renseigne réellement.', [('Attestation de formation','Aptitude attestée par la formation suivie'),('Décision ou titre CNAPS vérifié','Droit d’exercer pour les activités et la période concernées'),('Badge employeur','Identification dans l’entreprise'),('Planning','Affectation prévue par l’employeur')], 'Ces pièces se complètent sans se remplacer. Le planning n’autorise pas l’exercice, et un badge n’équivaut pas à une carte professionnelle valide.'),
     classify('Quels contrôles restent nécessaires avant confirmation ?', ['À vérifier', 'Ne suffit pas à autoriser'], [('Concordance du titulaire avec les justificatifs',0),('Activité couverte par le titre',0),('Validité du titre au moment de la mission',0),('Insistance du client sur l’ouverture à 08 h',1)], 'L’urgence commerciale ne réduit pas les conditions d’exercice. La vérification porte sur la situation actuelle de la bonne personne.'),
     choice('La capture ancienne indique « valide ». Quelle décision prend le responsable ?', 'Il réalise la vérification actuelle et résout l’écart d’identité avant confirmation.', ['Il utilise la capture jusqu’à la prochaine relève.', 'Il considère que le badge corrige la différence de nom.'], 'Une capture témoigne d’un état passé. L’écart peut être explicable, mais doit être documenté et vérifié, sans accusation préalable.'),
     sequence('Organisez la vérification de ce remplacement.', ['Rassembler le titre et les éléments d’identité nécessaires', 'Vérifier la situation actuelle et l’activité via le canal officiel', 'Faire résoudre l’écart par le service compétent', 'Confirmer une affectation compatible ou prévoir un autre agent'], 'La conclusion vient après la comparaison. Aucun temps passé à attendre n’est une autorisation implicite.'),
     choice('Le titulaire possède une autorisation préalable d’entrée en formation. Peut-elle remplacer sa carte pour travailler sur ce poste ?', 'Non, les deux documents correspondent à des finalités différentes.', ['Oui, puisqu’elle émane du même organisme.', 'Oui, si un titulaire de carte travaille à côté.'], 'Il faut distinguer accès à la formation et droit d’exercer. L’encadrement doit vérifier le titre réellement requis pour l’emploi.')])

dossier('01-03', 'Service interne ou entreprise prestataire ?',
    "Le service interne protège l’organisation dont il fait partie ; le prestataire fournit une prestation à un client. Cette distinction détermine des responsabilités et une organisation, mais ne supprime pas les règles applicables à l’activité de sécurité privée. L’identité de l’employeur, celle du bénéficiaire et la chaîne hiérarchique doivent être connues avant la prise de poste.\n\nUne personne qui accueille des visiteurs n’est pas automatiquement agent de sécurité. Il faut examiner les tâches réellement réalisées. Inversement, changer le nom d’un poste ne transforme pas une mission de surveillance en simple accueil. Lorsqu’un agent d’un service interne est envoyé sur un autre site ou pour une autre personne morale, le cadre doit être vérifié par le responsable : le lien économique entre deux sociétés ne suffit pas à établir que tout est autorisé.",
    [('Organisation du musée des Rives', 'Le musée emploie directement deux agents de son service interne de sécurité. Une entreprise extérieure assure la surveillance nocturne. Les hôtes d’accueil vendent les billets et orientent les visiteurs sans mission de surveillance.'),
     ('Demande de dernière minute', 'Une société voisine organise une exposition commerciale dans ses propres locaux. Son directeur demande au musée de lui prêter un agent interne, en expliquant que les deux structures partagent certains administrateurs.'),
     ('Consignes de coordination', 'Chaque employeur reste identifié dans le planning. Le responsable du musée coordonne les accès ; le chef de l’entreprise prestataire organise ses agents. Toute modification de bénéficiaire ou de mission est soumise à une vérification préalable du cadre administratif et contractuel.')],
    [classify('Classez les fonctions décrites, sans vous fier au seul intitulé.', ['Service interne', 'Prestataire de sécurité', 'Accueil sans surveillance'], [('Agent employé par le musée pour sa propre surveillance',0),('Agent de l’entreprise extérieure pendant la nuit',1),('Hôte qui vend les billets et oriente',2),('Agent de nuit chargé de surveiller les alarmes selon son contrat',1)], 'Le critère porte sur l’employeur et la mission réelle. Un uniforme ou la présence derrière une banque d’accueil ne suffit pas à déterminer le statut.'),
     associate('Associez les éléments qu’il faut établir.', [('Qui emploie l’agent ?','Lien hiérarchique'),('Pour qui la surveillance est-elle réalisée ?','Bénéficiaire de la mission'),('Quelles tâches sont confiées ?','Nature réelle de l’activité'),('Quels titres et autorisations s’appliquent ?','Cadre administratif')], 'Une analyse complète croise ces quatre questions ; elle ne s’arrête pas au nom du groupe ou du site.'),
     choice('Le prêt à la société voisine peut-il être confirmé sur le seul accord oral des directeurs ?', 'Non, le responsable doit faire vérifier le cadre avant cette affectation.', ['Oui, les administrateurs communs suffisent.', 'Oui, si le prêt dure moins d’une journée.'], 'La durée courte et la proximité des entreprises ne créent pas une exception générale. Il faut vérifier la situation exacte.'),
     sequence('Préparez la coordination du poste de nuit.', ['Identifier les agents, leur employeur et leur responsable', 'Vérifier le périmètre de surveillance et les consignes applicables', 'Confirmer les contacts et modalités de relais', 'Tracer les écarts signalés et les décisions confirmées'], 'La coordination du site ne doit pas rendre floue la chaîne de responsabilité des agents.'),
     choice('Un hôte reçoit désormais pour tâche permanente de surveiller les vols. Que faut-il examiner ?', 'La nouvelle mission réelle et les conditions d’exercice associées.', ['Seulement le nouvel intitulé sur son badge.', 'Seulement la possibilité de rester au comptoir.'], 'Des tâches de surveillance ne perdent pas leur nature parce qu’elles sont ajoutées à un poste nommé accueil.')])

dossier('01-04', 'Tenue, équipement et identité professionnelle',
    "La tenue permet au public d’identifier la sécurité privée sans la confondre avec les forces publiques. Les éléments réglementaires de marquage se vérifient avec les repères illustrés du cours et les textes applicables ; les préférences commerciales ne les remplacent pas. Le comportement et les mots employés participent aussi à cette distinction.\n\nLa mission ordinaire d’un agent de surveillance n’autorise pas, par elle-même, le port d’une arme. Une demande du client, un équipement acheté personnellement ou une formation générale ne constituent pas le cadre spécifique nécessaire. Avant toute prise de poste, contrôlez la tenue, le matériel prévu, les consignes et les limites de mission. Un écart doit être traité avec l’encadrement, sans improvisation d’insigne, de pouvoir ou d’équipement.",
    [('Contrat de la galerie Solstice', 'Mission de surveillance humaine non armée. La tenue professionnelle de l’entreprise est prévue au vestiaire avec les identifiants réglementaires. L’agent dispose d’une radio et des contacts du chef de poste.'),
     ('Veste proposée par un exposant', 'Un exposant fournit une veste évoquant une unité publique et propose de masquer les identifiants de sécurité privée pour rendre la présence plus dissuasive. Il demande aussi d’emporter un équipement de défense personnel.'),
     ('Situation à l’entrée', 'Un visiteur demande à l’agent s’il est policier. Un collègue suggère de répondre simplement « service de contrôle » afin de ne pas perdre d’autorité. Le chef de poste peut apporter une tenue adaptée et confirmer le matériel autorisé.')],
    [classify('Séparez les éléments compatibles de ceux à faire corriger.', ['Compatible avec la mission décrite', 'Écart à signaler'], [('Radio et contacts du chef de poste',0),('Masquage des identifiants de sécurité privée',1),('Équipement de défense personnel non prévu ni autorisé',1),('Tenue professionnelle avec marquages conformes',0)], 'La dissuasion ne justifie ni confusion avec un service public ni équipement non autorisé. Le contrôle porte sur le cadre réellement prévu.'),
     associate('Quel repère répond à chaque difficulté ?', [('Le visiteur pense parler à un policier','Expliquer sa qualité d’agent de sécurité privée'),('La veste masque les marquages','Faire rétablir une tenue adaptée'),('Le client demande un équipement armé','Vérifier le cadre spécifique avec l’encadrement'),('Le matériel de liaison manque','Faire assurer les moyens de communication du poste')], 'Ces difficultés sont distinctes : une bonne radio ne corrige pas une tenue trompeuse, et une tenue conforme n’élargit pas les pouvoirs.'),
     choice('Quelle réponse au visiteur est la plus précise ?', '« Je suis agent de sécurité privée de la galerie ; je vous explique la règle d’accès du site. »', ['« Je représente les autorités pour tous les contrôles ici. »', '« Mon statut importe peu ; vous devez me remettre vos papiers. »'], 'L’autorité professionnelle repose sur une règle d’accès expliquée et sur une mission claire, sans usurpation de qualité.'),
     sequence('Traitez les écarts avant la prise de poste.', ['Comparer la tenue et le matériel à la mission prévue', 'Signaler la veste et l’équipement inadaptés au responsable', 'Obtenir les moyens conformes et la confirmation du poste', 'Conserver la trace utile des écarts et de leur résolution'], 'Faire corriger un écart est une démarche professionnelle. Il ne faut pas improviser un nouveau signe distinctif.'),
     choice('La veste proposée est remplacée, mais le collègue continue à se présenter comme policier. Le problème est-il résolu ?', 'Non, la présentation orale doit également rester exacte.', ['Oui, seule la couleur de la tenue compte.', 'Oui, si aucun visiteur ne se plaint.'], 'L’absence de plainte ne rend pas une présentation trompeuse acceptable. Les gestes, les mots et la tenue doivent rester cohérents.')])

dossier('02-01', 'Un dommage et plusieurs responsabilités',
    "Un même événement peut soulever des questions différentes : réparer un dommage, rechercher une infraction ou examiner le respect d’une règle professionnelle. Ne les confondez pas avec une déclaration immédiate de culpabilité. Décrire les faits, identifier les sources et conserver les éléments utiles précèdent leur qualification par les autorités compétentes.\n\nUne instruction de l’employeur ne fait pas disparaître la responsabilité personnelle. Pour examiner sa conduite, l’agent doit relier le risque connu, les moyens disponibles, les actions réellement réalisées et leurs effets. Une transmission honnête indique aussi ce qu’il n’a pas vu. Elle n’attribue pas au collègue, au client ou à la victime une responsabilité que les faits ne permettent pas d’établir.",
    [('Journal du parking', 'À 17 h 02, une barrière se ferme sur le véhicule d’un visiteur. L’agent a actionné la commande après avoir reçu une demande radio de fermeture. Il déclare ne pas avoir vu la voiture dans l’angle mort.'),
     ('Consigne de fonctionnement', 'Avant fermeture, vérifier que le passage est libre. Si la visibilité est insuffisante, obtenir une confirmation d’un agent placé en sécurité. Le poste dispose d’un bouton d’arrêt et d’un contact technique.'),
     ('Éléments disponibles', 'Le visiteur signale une aile endommagée. Le collègue confirme avoir demandé la fermeture, sans avoir contrôlé le passage. Une caméra peut contenir des images, accessibles uniquement aux personnes habilitées. Aucun constat médical n’est disponible.')],
    [classify('Distinguez les niveaux de certitude.', ['Fait documenté', 'Déclaration à attribuer', 'Conclusion non établie'], [('La fermeture est enregistrée à 17 h 02',0),('L’agent indique ne pas avoir vu la voiture',1),('L’agent a volontairement endommagé le véhicule',2),('Le visiteur signale une aile endommagée',1)], 'L’intention ne découle pas automatiquement du dommage. Une déclaration conserve sa source même si elle semble vraisemblable.'),
     associate('Quelle question examine-t-on ?', [('Qui doit réparer le dommage ?','Responsabilité civile'),('Une infraction est-elle constituée ?','Responsabilité pénale'),('Une règle de travail a-t-elle été méconnue ?','Responsabilité disciplinaire'),('Que montrent les éléments conservés ?','Établissement des faits')], 'Plusieurs voies peuvent concerner le même fait ; l’agent ne remplace ni l’enquête ni la juridiction.'),
     choice('Quelle pièce rapproche directement la conduite attendue du geste réalisé ?', 'La consigne de contrôle du passage, comparée au journal et aux déclarations.', ['Le montant estimé de la réparation seul.', 'L’ancienneté du collègue qui a donné l’ordre.'], 'L’analyse compare la règle de prudence aux faits précis ; l’ancienneté ne vaut pas contrôle du passage.'),
     sequence('Après mise en sécurité, préparez le compte rendu.', ['Noter l’heure, le lieu et les actions observées', 'Attribuer distinctement les déclarations de chacun', 'Signaler les éléments utiles à préserver par les personnes habilitées', 'Transmettre sans conclure seul sur les responsabilités'], 'L’ordre proposé construit un récit vérifiable, sans effacer les incertitudes.'),
     choice('Le collègue demande d’omettre son message radio. Quelle réponse retenir ?', 'Conserver les faits utiles, dont le message, sans accusation ni dissimulation.', ['Retirer le message pour faciliter le règlement amiable.', 'Présenter le collègue comme seul responsable.'], 'Ni omission volontaire ni accusation hâtive : la précision protège la qualité du traitement.')])

dossier('02-02', 'La menace cesse pendant l’intervention',
    "La légitime défense s’apprécie à partir d’une atteinte injustifiée et actuelle, de la nécessité de la réponse et de sa proportionnalité. Il faut raisonner à l’instant de l’action, puis réévaluer quand les faits changent. Une réaction compréhensible sous l’émotion n’est pas automatiquement juridiquement justifiée.\n\nProtéger une personne et poursuivre un auteur pour le punir répondent à deux logiques différentes. La fin de l’agression modifie les moyens nécessaires. L’agent décrit la menace perçue, les possibilités de protection et le moment où son action a cessé. Les règles de défense des personnes et des biens comportent des conditions propres ; on ne transpose pas mécaniquement une solution d’un cas à l’autre.",
    [('Observation au gymnase', 'À 20 h 10, un individu pousse un spectateur contre une barrière et lève à nouveau le poing. Un agent se trouve à proximité. Un autre peut appeler les secours et la police.'),
     ('Évolution', 'Après une intervention de protection, l’individu recule, baisse les bras puis s’éloigne. Le spectateur reste au sol. Un proche demande à l’agent de poursuivre l’individu pour lui donner une leçon.'),
     ('Moyens et témoins', 'Une sortie dégagée permet de mettre le spectateur à l’écart. Deux témoins ont vu le début de l’agression ; un troisième n’a vu que la fin. Les secours sont joignables par le poste central.')],
    [classify('Que permet d’établir chaque élément ?', ['Menace actuelle au début', 'Changement imposant réévaluation', 'Ne justifie pas une punition'], [('Poing levé vers le spectateur déjà poussé',0),('Recul et bras baissés',1),('Demande du proche de donner une leçon',2),('Éloignement de l’individu',1)], 'L’analyse est temporelle. Un fait initial ne justifie pas sans limite les actes réalisés après sa disparition.'),
     associate('Associez les questions aux critères.', [('L’attaque se produit-elle encore ?','Actualité'),('Quel moyen protège effectivement la personne ?','Nécessité'),('La réponse est-elle adaptée à la gravité ?','Proportionnalité'),('La réaction sert-elle à punir après coup ?','Risque de représailles')], 'Chaque critère répond à une question distincte. L’énervement de l’entourage n’étend aucun pouvoir.'),
     choice('Au moment où l’individu s’éloigne sans menacer, quelle priorité ressort du dossier ?', 'Réévaluer, protéger le spectateur et assurer l’alerte et les secours.', ['Maintenir la même force puisque l’agression a commencé.', 'Le poursuivre pour obtenir des excuses.'], 'L’arrêt de l’atteinte oblige à ajuster l’action. Un éventuel cadre d’interpellation doit être examiné séparément, sans représailles.'),
     sequence('Présentez les faits dans leur ordre.', ['Poussée et poing levé observés', 'Action de protection réalisée', 'Recul et arrêt de la menace observés', 'Protection du spectateur et relais aux secours'], 'Cette chronologie permet d’examiner la justification de chaque action à son instant.'),
     choice('Quel témoin peut décrire le début de l’atteinte ?', 'Les deux témoins qui l’ont effectivement vu, en distinguant leurs déclarations.', ['Le troisième témoin comme les deux autres.', 'Uniquement le proche le plus affirmatif.'], 'La force d’une affirmation ne remplace pas la possibilité réelle d’observer.')])

dossier('02-03', 'Assister dans un local enfumé',
    "L’assistance ne consiste pas à ajouter une victime. Analysez le péril, ce que vous pouvez faire sans risque pour vous ou pour les tiers, et les moyens d’alerter ou de provoquer une aide. Une alerte précise et une protection du périmètre peuvent être essentielles lorsque l’accès direct est dangereux.\n\nNe confondez pas état de nécessité et permission générale de prendre n’importe quel risque. L’acte doit répondre à un danger actuel ou imminent et rester proportionné. L’agent explique le danger, l’action choisie, les limites rencontrées et le relais demandé. Les gestes de secours se réalisent dans le cadre des compétences acquises et des instructions des secours ; une séquence en ligne ne remplace pas l’entraînement pratique.",
    [('Ronde dans un atelier', 'L’agent voit de la fumée s’échapper d’un local fermé. Il entend une personne appeler. Il ne dispose pas d’équipement pour entrer dans une atmosphère dangereuse.'),
     ('Organisation du site', 'Le poste central peut déclencher l’alerte interne et accueillir les pompiers. Un point sûr permet de téléphoner. Des salariés arrivent vers le couloir, sans avoir vu la fumée.'),
     ('Évolution à transmettre', 'La personne répond encore depuis l’intérieur. L’origine de la fumée et l’état de l’installation sont inconnus. La porte d’accès des secours est dégagée. Un salarié propose d’entrer en retenant sa respiration.')],
    [classify('Classez les mesures proposées.', ['Aide réalisable depuis une zone sûre', 'Expose à un danger non maîtrisé'], [('Alerter en donnant accès et localisation',0),('Entrer en retenant sa respiration',1),('Écarter les salariés du couloir exposé',0),('Chercher la source de fumée à l’intérieur',1)], 'L’absence d’équipement et l’atmosphère inconnue rendent l’entrée dangereuse. Alerter et empêcher d’autres expositions sont des actions d’assistance.'),
     associate('Reliez l’information à son utilité pour les secours.', [('Personne entendue dans le local','Victime potentielle'),('Atelier et porte concernés','Localisation'),('Fumée et origine inconnue','Danger et incertitude'),('Accès dégagé et accueil organisé','Acheminement des secours')], 'Une alerte concrète réduit les recherches sans inventer la cause de l’incident.'),
     choice('Quelle formulation décrit correctement l’incertitude ?', '« Fumée visible, personne entendue, origine non identifiée. »', ['« Incendie électrique confirmé, victime intoxiquée. »', '« Rien de grave tant que la personne répond. »'], 'On transmet les signes observés, sans diagnostic technique ni médical non établi.'),
     sequence('Organisez la réponse depuis le point sûr.', ['Se protéger et empêcher une nouvelle exposition', 'Alerter les secours avec les faits disponibles', 'Mettre en œuvre les consignes reçues sans entrer en zone dangereuse', 'Accueillir et informer les intervenants'], 'Les actions peuvent se répartir entre collègues ; la protection et l’alerte ne doivent pas attendre un compte rendu complet.'),
     choice('La personne cesse de répondre. Que change cette information ?', 'Elle aggrave l’urgence à transmettre, sans rendre l’entrée sûre.', ['Elle supprime le risque lié à la fumée.', 'Elle permet de différer l’appel jusqu’à l’arrivée du responsable.'], 'Une évolution de la victime est immédiatement utile aux secours. Elle ne change pas les limites du matériel disponible.')])

dossier('03-01', 'Un signal antivol et des faits incomplets',
    "L’article 73 du code de procédure pénale vise un crime flagrant ou un délit flagrant puni d’emprisonnement et la conduite de l’auteur devant l’officier de police judiciaire le plus proche. Ce cadre ne transforme pas tout soupçon en droit d’interpellation. L’agent doit distinguer ses observations, les déclarations de tiers et une simple alarme.\n\nUn dispositif antivol indique un événement technique ; il ne démontre pas à lui seul un vol. L’observation peut être fragmentaire ou compatible avec une explication légitime. Cherchez ce qui est réellement établi, signalez ce qui manque et évitez d’ajouter une contrainte sans fondement. Le refus d’un contrôle volontaire ne constitue pas, par lui-même, la preuve de l’infraction recherchée.",
    [('Sortie du magasin Mosaïque', 'À 11 h 05, le portique sonne au passage d’un client. L’agent n’a pas suivi ses achats. Une caissière indique qu’une étiquette a peut-être été mal désactivée.'),
     ('Déclaration d’un vendeur', 'Le vendeur a vu le client prendre un article puis l’a perdu de vue avant les caisses. Il n’a pas constaté le franchissement des caisses sans paiement.'),
     ('Échange avec le client', 'Le client présente volontairement un ticket dont certaines lignes sont difficiles à lire. Il refuse que l’agent fouille son sac. Le responsable de caisse est disponible pour vérifier le ticket avec lui.')],
    [classify('Quelle est la nature de ces éléments ?', ['Observation directe', 'Déclaration de tiers', 'Déduction non établie'], [('Le portique a sonné',0),('L’étiquette serait mal désactivée selon la caissière',1),('Le client a nécessairement volé',2),('Le vendeur a perdu le client de vue avant les caisses',1)], 'L’alarme et les témoignages partiels appellent une vérification ; ils ne démontrent pas tous les éléments d’un vol flagrant.'),
     associate('Associez chaque limite à sa conséquence.', [('Achats non suivis','Ne pas inventer une continuité d’observation'),('Ticket peu lisible','Demander une vérification de caisse consentie'),('Fouille refusée','Ne pas imposer la fouille au seul motif du refus'),('Alarme technique','Ne pas la confondre avec une preuve complète')], 'Les limites d’information doivent rester visibles dans le raisonnement.'),
     choice('Quelle démarche est fondée sur les éléments disponibles ?', 'Expliquer l’alarme et proposer une vérification avec le responsable de caisse.', ['Retenir automatiquement le client jusqu’à une reconnaissance de vol.', 'Fouiller le sac puisque le portique a sonné.'], 'Le cas ne justifie pas une contrainte automatique. On privilégie une clarification dans les limites du droit applicable.'),
     sequence('Construisez un compte rendu sans surinterpréter.', ['Noter le signal et l’heure', 'Attribuer les propos du vendeur et de la caissière', 'Préciser les vérifications proposées et la réponse du client', 'Transmettre les faits et les incertitudes au responsable'], 'Le compte rendu permet de revoir la décision sans transformer des hypothèses en faits.'),
     choice('Le responsable confirme ensuite le paiement de l’article. Que faire de l’hypothèse initiale ?', 'Mentionner la vérification et son résultat, puis clore la difficulté conformément aux consignes.', ['Conserver l’accusation parce que le client a refusé la fouille.', 'Effacer toute trace de l’événement.'], 'Un résultat nouveau doit corriger l’analyse tout en conservant une trace factuelle et proportionnée.')])

dossier('03-02', 'Un relais aux forces de l’ordre sans enquête privée',
    "Lorsqu’une situation relève effectivement de l’article 73, la finalité est le relais rapide à l’officier de police judiciaire, pas l’obtention d’un aveu ou l’organisation d’une enquête privée. Les mesures employées doivent rester nécessaires et proportionnées à la situation ; toute évolution impose une réévaluation.\n\nLa transmission doit rendre compréhensible le lien entre les observations et l’intervention. Distinguez l’heure des faits, celle de l’appel et celle de la remise aux forces de l’ordre. Signalez immédiatement une blessure ou un malaise. Le temps passé à attendre ne donne pas de nouveaux pouvoirs d’interrogatoire ni de fouille ; l’agent suit les instructions reçues et préserve la dignité des personnes.",
    [('Observation dans une réserve', 'Un agent voit une personne forcer une porte, prendre une caisse puis tenter de sortir. Il transmet immédiatement les faits au poste central. La situation est portée à la connaissance de la police ; aucune confession n’a été demandée.'),
     ('Demandes du responsable commercial', 'Le responsable veut faire signer un texte reconnaissant les faits et photographier le contenu du téléphone de la personne. Il propose de retarder l’appel pour évaluer la perte.'),
     ('Suivi de l’événement', 'Le poste dispose d’un journal horaire et du nom de l’agent témoin. La personne dit avoir mal au poignet. Les forces de l’ordre demandent la localisation précise et les conditions d’accès.')],
    [classify('Quelles actions correspondent à la finalité du relais ?', ['À réaliser dans le cadre adapté', 'Ne relève pas de cette finalité'], [('Transmettre immédiatement les faits à la police',0),('Faire signer un aveu',1),('Explorer le téléphone pour chercher des preuves',1),('Signaler la douleur et demander l’aide nécessaire',0)], 'Le relais n’est pas une garde à vue privée. La santé et la dignité restent prises en compte.'),
     associate('Quelle information sert à quoi ?', [('Heure du forçage observé','Chronologie des faits'),('Heure de l’appel','Chronologie de l’alerte'),('Douleur au poignet déclarée','Besoin de prise en charge à signaler'),('Accès à la réserve','Orientation des intervenants')], 'Une chronologie précise ne dispense pas de préciser la source et les incertitudes de chaque élément.'),
     choice('La demande de chiffrer la perte peut-elle retarder le relais ?', 'Non, le chiffrage commercial ne remplace pas le relais rapide aux autorités.', ['Oui, si le montant peut éviter une plainte.', 'Oui, jusqu’à la signature d’un document.'], 'La finalité du cadre d’interpellation demeure la remise aux autorités, non la négociation commerciale.'),
     sequence('Ordonnez les informations du rapport de remise.', ['Faits personnellement observés', 'Action réalisée et heure de l’alerte', 'Évolution, douleur signalée et mesures de protection', 'Heure et destinataire du relais'], 'Le rapport décrit ce qui s’est produit ; il n’ajoute pas une qualification définitive de culpabilité.'),
     choice('Une fois les policiers présents, que transmettre sur le téléphone ?', 'La demande du responsable si elle est utile, sans avoir exploré le contenu.', ['Les messages copiés pour gagner du temps.', 'Une supposition sur ce que contient l’appareil.'], 'Préserver un élément ne signifie pas l’exploiter soi-même hors de ses pouvoirs.')])

dossier('04-01', 'Une demande d’images et un fichier visiteurs',
    "Une donnée personnelle permet d’identifier directement ou indirectement une personne. Le besoin de sécurité ne justifie pas une collecte illimitée ni une diffusion à tout demandeur. Vérifiez la finalité, les personnes habilitées, le canal de transmission et les règles de conservation applicables au dispositif.\n\nL’accès professionnel repose sur le besoin d’en connaître. Une demande d’un collègue, d’un commerçant ou d’un proche n’équivaut pas à une habilitation. Orientez les demandes de droit d’accès et celles des autorités vers la procédure prévue, avec vérification de leur qualité. Ne promettez pas une suppression ou une remise immédiate que vous n’êtes pas autorisé à effectuer.",
    [('Registre d’une pépinière d’entreprises', 'Le registre contient nom, entreprise visitée, heure d’entrée et heure de sortie. Il est accessible aux personnels habilités chargés de l’accueil et de la sécurité. La consigne prévoit la transmission des demandes au responsable du traitement.'),
     ('Deux demandes à 15 h', 'Un commerçant voisin veut la liste des visiteurs pour une opération commerciale. Une visiteuse demande les images où elle apparaît après avoir perdu son sac. Elle ne demande pas les images des autres personnes.'),
     ('Pratiques à corriger', 'Un agent laisse son compte ouvert pendant la pause. Un collègue propose d’envoyer les captures vidéo sur son téléphone personnel pour les examiner ce soir. Le responsable peut recevoir les demandes par le canal professionnel prévu.')],
    [classify('Classez les usages proposés.', ['Finalité sécurité à traiter par la procédure', 'Usage ou accès à écarter'], [('Demande de la visiteuse à transmettre au responsable',0),('Liste visiteurs pour prospection commerciale du voisin',1),('Captures sur téléphone personnel pour examen à domicile',1),('Consultation par une personne habilitée pour l’incident',0)], 'Une finalité légitime n’autorise pas tous les canaux. La demande de la visiteuse doit aussi respecter les droits des tiers.'),
     associate('Reliez chaque mesure à son objectif.', [('Verrouiller sa session','Éviter l’accès sous son identité'),('Limiter les champs du registre au besoin défini','Minimiser les données'),('Vérifier l’habilitation du destinataire','Limiter la communication'),('Appliquer la durée de conservation prévue','Éviter une conservation indéfinie')], 'Ces mesures répondent à des risques différents et se complètent.'),
     choice('Quelle réponse donner à la visiteuse ?', 'Expliquer le canal de demande et la transmettre selon la procédure, sans envoyer soi-même les images.', ['Refuser toute demande car la sécurité interdit tout accès.', 'Exporter immédiatement toutes les images de l’après-midi.'], 'Le droit d’accès doit être traité par le responsable compétent, avec les vérifications et protections nécessaires.'),
     sequence('Traitez le départ en pause devant le poste.', ['Terminer ou sécuriser l’opération en cours', 'Verrouiller la session individuelle', 'Transmettre la relève par le canal autorisé', 'Reprendre avec son propre compte au retour'], 'Le compte partagé ou laissé ouvert empêche d’attribuer correctement les actions.'),
     choice('Une demande reçue par courriel se présente comme venant de la police. Que vérifier avant une transmission ?', 'L’authenticité et le cadre de la demande par la procédure professionnelle.', ['Seulement la présence d’un logo.', 'Seulement le caractère urgent du message.'], 'Une apparence officielle ne suffit pas. Utilisez les contacts et circuits validés pour vérifier le destinataire et la demande.')])

dossier('05-01', 'La même règle d’accès, des besoins différents',
    "Traiter les personnes avec égalité suppose d’appliquer des critères liés à la situation, sans discrimination. Une règle d’accès doit pouvoir être expliquée par une condition vérifiable : droit d’entrée, capacité, autorisation de zone ou mesure de sécurité. L’apparence, l’origine supposée ou un jugement sur la personne ne sont pas des critères de remplacement.\n\nL’égalité n’impose pas d’ignorer un besoin d’accessibilité. Un aménagement peut permettre d’atteindre la même finalité de sécurité sans humilier ni exclure. L’agent vérifie les options prévues et sollicite l’interlocuteur compétent, sans promettre une dérogation qu’il ne maîtrise pas. La dignité se préserve aussi dans le choix du lieu et des mots employés.",
    [('Règlement d’un salon professionnel', 'L’accès exige un billet valable pour la journée. Une entrée accessible est prévue avec le même contrôle du billet. Le poste d’accueil peut résoudre les difficultés de lecture du code.'),
     ('Trois arrivées', 'Une personne en fauteuil possède un billet valide ; l’entrée principale comporte des marches. Un visiteur sans billet est connu du responsable. Une troisième personne possède un code endommagé et souhaite une vérification.'),
     ('Consigne orale contestable', 'Un exposant demande de contrôler plus longuement les personnes qui lui semblent étrangères. Il ne signale aucun fait concret ni incident. Le responsable du contrôle est joignable.')],
    [classify('Quels critères sont pertinents pour ce contrôle ?', ['Critère lié au droit d’accès', 'Critère à écarter'], [('Validité du billet pour aujourd’hui',0),('Origine supposée par un exposant',1),('Autorisation d’accès confirmée par le service compétent',0),('Connaissance personnelle sans validation de billet',1)], 'Le contrôle s’appuie sur des conditions objectives et vérifiables, pas sur une appartenance supposée.'),
     associate('Quel traitement convient à chaque situation ?', [('Billet valide et marches infranchissables','Orientation vers l’entrée accessible avec contrôle équivalent'),('Ami du responsable sans billet','Vérification du droit d’accès selon la procédure'),('Code endommagé','Relais au poste de vérification'),('Demande fondée sur l’origine supposée','Refus du critère et signalement à l’encadrement')], 'Adapter le cheminement préserve l’accès sans supprimer le contrôle justifié.'),
     choice('Quelle explication respecte la dignité ?', '« Nous vérifions la validité du billet ; je vous indique le passage accessible. »', ['« Votre situation impose de vous mettre à l’écart de tous. »', '« L’entrée accessible dispense de toute vérification. »'], 'On explique la règle et l’aide proposée sans réduire la personne à sa situation.'),
     sequence('Résolvez le code endommagé.', ['Expliquer la difficulté de lecture du code', 'Orienter vers la vérification prévue sans bloquer le flux', 'Attendre la confirmation du droit d’accès', 'Appliquer le résultat avec une explication claire'], 'Le défaut technique ne prouve ni fraude ni absence de billet.'),
     choice('Le code est finalement valide. Faut-il conserver la personne sous surveillance renforcée pour cette seule raison ?', 'Non, la difficulté technique résolue ne constitue pas un indice de menace.', ['Oui, tout contrôle inhabituel justifie une surveillance renforcée.', 'Oui, si l’exposant l’avait demandé.'], 'La décision doit rester reliée aux faits actuels et à la finalité de sécurité.')])

dossier('05-02', 'Convictions et consignes sur un site privé',
    "Il faut distinguer la neutralité du service public, les obligations propres aux professionnels et les droits des usagers. On ne transpose pas automatiquement une règle applicable aux agents d’un service public à chaque visiteur d’un site privé. Une restriction se vérifie dans son cadre réel et ne s’invente pas au poste d’accès.\n\nL’agent reste impartial dans sa mission : il n’engage pas de débat religieux ou politique pour décider d’une entrée. Il s’appuie sur la règle applicable, les faits et le respect de la dignité. Une difficulté liée à l’identification ou à une mesure de sécurité appelle une solution conforme à la procédure, expliquée calmement et traitée par le bon responsable.",
    [('Maison des associations, événement privé', 'Le contrôle prévu porte sur le billet et l’autorisation d’accéder à la salle réservée. Aucune consigne du dossier n’interdit les signes de conviction des visiteurs.'),
     ('Échange à l’entrée', 'Un bénévole demande de refuser une visiteuse portant un signe religieux visible. Son billet est valide et aucun comportement menaçant n’est observé. Il invoque simplement « la laïcité partout ».'),
     ('Autre situation', 'Un participant tente de distribuer des tracts dans un passage où toute distribution est interdite pour préserver la circulation, quel qu’en soit le contenu. Le responsable peut confirmer cette règle de fonctionnement.')],
    [classify('Quel fondement est fourni par le dossier ?', ['Règle de fonctionnement objective', 'Restriction non établie'], [('Vérifier le billet de la visiteuse',0),('Refuser son entrée pour le signe visible seul',1),('Empêcher toute distribution dans le passage encombré',0),('Interdire uniquement les tracts d’une opinion déplaisante',1)], 'La règle décrite vise la circulation, pas une opinion. Le dossier ne fournit pas de fondement au refus lié au signe visible.'),
     associate('Distinguez les sujets à examiner.', [('Droit d’entrée','Billet et zone autorisée'),('Distribution dans un passage','Règle de circulation du site'),('Demande du bénévole','Instruction à confronter au cadre applicable'),('Conviction personnelle de l’agent','Ne doit pas décider du traitement du visiteur')], 'Séparer les sujets évite de présenter une préférence comme une règle juridique.'),
     choice('Comment répondre au bénévole ?', 'Demander le fondement de la restriction et saisir le responsable sans appliquer une interdiction inventée.', ['Appliquer le refus pour éviter un débat.', 'Interroger la visiteuse sur ses convictions avant de décider.'], 'L’agent ne crée pas une restriction et n’a pas à enquêter sur les convictions du visiteur.'),
     sequence('Traitez la distribution dans le passage.', ['Vérifier la règle et la gêne à la circulation', 'Expliquer la même limite à tous les distributeurs', 'Indiquer le relais ou le lieu autorisé s’il existe', 'Signaler un refus persistant selon la procédure'], 'La règle doit rester cohérente, nécessaire à sa finalité et appliquée sans sélection des opinions.'),
     choice('Le tract porte une opinion que l’agent partage. La règle de circulation change-t-elle ?', 'Non, le même critère de circulation s’applique.', ['Oui, si l’agent juge l’opinion utile.', 'Oui, si le distributeur est bénévole.'], 'L’impartialité protège la crédibilité et la légitimité du contrôle.')])

dossier('05-03', 'Quand le règlement contredit les droits',
    "Un règlement de site organise le fonctionnement mais reste soumis aux textes de niveau supérieur. L’agent ne déduit pas la légalité d’une mesure de la seule présence d’un logo, d’une signature ou du mot obligatoire. Il doit savoir reconnaître une difficulté et la transmettre au responsable compétent.\n\nLa loi protège les personnes et encadre les pouvoirs. Elle s’applique aussi lorsqu’un groupe ou un client réclame une mesure arbitraire. Pour justifier une décision, explicitez le fait constaté, la règle pertinente et l’action proportionnée. Le désaccord d’un usager ne le prive pas de ses droits ; il ne transforme pas une règle interne en pouvoir de contrainte.",
    [('Règlement remis à un agent', 'Une version non datée demande de conserver les pièces d’identité des visiteurs qui contestent une décision d’accès. Une version récente prévoit seulement d’appeler le responsable pour les contestations.'),
     ('Incident', 'Un visiteur refuse de laisser son document comme garantie. Il parle calmement et demande à connaître le motif de refus d’entrée. Il ne menace personne et n’essaie pas de forcer l’accès.'),
     ('Ressources', 'Le responsable dispose de la version validée du règlement et du contact du service compétent. Une zone d’attente permet de poursuivre l’échange sans gêner les autres visiteurs.')],
    [classify('Quels éléments peuvent guider la décision ?', ['Élément à prendre en compte', 'Ne crée pas un pouvoir'], [('Version validée et à jour du règlement',0),('Mot obligatoire sur une ancienne feuille',1),('Absence de menace et de passage en force',0),('Agacement d’un collègue face à la contestation',1)], 'Il faut croiser le cadre et les faits, sans laisser une mention ancienne ou une émotion créer une contrainte.'),
     associate('Associez chaque vérification à son but.', [('Date et validation du document','Identifier la consigne applicable'),('Compatibilité avec les droits','Écarter une mesure arbitraire'),('Comportement réellement observé','Adapter la réponse au fait'),('Contact du responsable','Obtenir une décision traçable')], 'Une chaîne de vérifications est plus robuste qu’une réaction fondée sur une formule isolée.'),
     choice('Quelle action est justifiée ici ?', 'Expliquer le motif d’accès, saisir le responsable et ne pas retenir le document comme garantie.', ['Conserver le document jusqu’à l’arrêt de la contestation.', 'Menacer d’une sanction pénale pour toute discussion.'], 'La contestation calme ne constitue pas un motif de confiscation. Une règle interne ne crée pas ce pouvoir.'),
     sequence('Traitez la contradiction entre les consignes.', ['Repérer les versions et la contradiction', 'Maintenir les seules mesures d’accès justifiées', 'Faire confirmer la règle par le responsable', 'Signaler le document obsolète pour retrait du circuit'], 'Le retrait documentaire relève de l’organisation ; le signalement évite que l’erreur se reproduise.'),
     choice('Le visiteur demande une explication écrite. Quelle attitude adopter ?', 'L’orienter vers le canal prévu pour obtenir une réponse du responsable.', ['Refuser tout échange car il conteste.', 'Inventer un article de loi pour clore la discussion.'], 'Une explication doit être exacte et donnée par le bon interlocuteur, sans référence fabriquée.')])

dossier('06-01', 'Une faveur à l’entrée du chantier',
    "Un passe-droit peut sembler anodin lorsqu’il vient d’une personne connue. Le risque apparaît lorsque la relation personnelle remplace une condition de sécurité : autorisation, créneau, escorte ou équipement. Les cadeaux et avantages susceptibles d’influencer la mission doivent être traités selon les règles déontologiques et internes.\n\nLe refus professionnel se formule sur la règle et sur une solution possible : faire vérifier l’autorisation, joindre l’interlocuteur habilité, proposer le circuit normal. Il ne nécessite ni accusation publique ni conflit. Conservez une trace utile de la sollicitation et de la réponse sans ajouter de jugement sur la moralité de la personne.",
    [('Accès chantier Véra', 'Les entreprises intervenantes sont inscrites au planning et accueillies par un référent. Une livraison supplémentaire nécessite la confirmation du coordinateur. Le gardien ne peut pas modifier seul la liste.'),
     ('Demande d’un habitué', 'Un livreur connu arrive hors créneau avec un collègue non inscrit. Il propose deux places de spectacle à l’agent s’il les laisse passer. Il dit que personne ne contrôlera la liste.'),
     ('Solution disponible', 'Le coordinateur répond au téléphone. Une zone d’attente sûre permet de vérifier la livraison. Le collègue du livreur dispose de documents à présenter au coordinateur, mais aucune confirmation n’a encore été donnée.')],
    [classify('Quels éléments peuvent autoriser la suite ?', ['Condition professionnelle à vérifier', 'Ne remplace pas une autorisation'], [('Confirmation du coordinateur',0),('Livreur connu de l’agent',1),('Places de spectacle proposées',1),('Identité et inscription des intervenants confirmées',0)], 'Une relation habituelle ne supprime pas la vérification d’une nouvelle personne ou d’un nouveau créneau.'),
     associate('Associez la réponse à l’écart.', [('Hors créneau','Faire confirmer la livraison'),('Collègue non inscrit','Faire vérifier son droit d’accès'),('Avantage proposé','Refuser l’influence et signaler selon les règles'),('Camion à l’entrée','Orienter vers l’attente sûre prévue')], 'Traiter chaque écart rend le refus utile et évite de bloquer inutilement le site.'),
     choice('Quelle phrase convient ?', '« Je dois faire confirmer votre accès ; vous pouvez attendre ici pendant la vérification. »', ['« Avec un petit geste, je peux oublier la liste. »', '« Vous êtes forcément fraudeurs puisque vous êtes en retard. »'], 'On explique le contrôle sans accepter d’avantage ni conclure sur une intention.'),
     sequence('Traitez la sollicitation.', ['Maintenir l’accès en attente dans la zone prévue', 'Refuser l’avantage et demander la vérification officielle', 'Appliquer la décision du coordinateur dans son cadre', 'Tracer la sollicitation et le traitement utile'], 'L’avantage ne doit jamais conditionner la décision, même si l’accès est ensuite autorisé régulièrement.'),
     choice('L’accès est finalement confirmé. Peut-on accepter les places comme remerciement pour la dérogation ?', 'Non, il faut conserver une décision indépendante et appliquer les règles relatives aux avantages.', ['Oui, la confirmation rend le cadeau sans effet.', 'Oui, si l’offre reste confidentielle.'], 'Une confirmation régulière ne transforme pas une tentative d’influence en faveur à rémunérer.')])

dossier('06-02', 'Une information vraie peut rester confidentielle',
    "L’exactitude d’une information n’autorise pas sa diffusion. Les informations recueillies dans la mission suivent un circuit professionnel et un besoin d’en connaître. Un collègue d’un autre site, un proche ou un client non habilité ne devient pas destinataire parce qu’il manifeste de l’intérêt.\n\nLe devoir de discrétion ne signifie pas dissimuler un incident aux interlocuteurs compétents. Il faut transmettre assez pour agir, par le canal adapté, en limitant les détails sans utilité. Une demande extérieure inhabituelle mérite une vérification d’identité et d’habilitation. Le compte rendu professionnel doit rester séparé des échanges personnels et des réseaux sociaux.",
    [('Incident dans une clinique', 'Un visiteur a contesté une restriction d’accès. La main courante mentionne l’heure, le service concerné et le relais au responsable. Des informations de santé apparaissent sur un document visible à l’accueil.'),
     ('Messages reçus', 'Un ami de l’agent demande le nom du patient concerné. Un collègue non affecté au site demande une capture de la main courante « pour comprendre ». Le responsable sécurité demande un rapport factuel par le canal professionnel.'),
     ('Consigne de confidentialité', 'Ne transmettre que les éléments utiles aux personnes habilitées. Les documents laissés visibles doivent être protégés et signalés au service concerné. Les messageries personnelles ne sont pas prévues pour ces transmissions.')],
    [classify('Quelle destination convient ?', ['Circuit professionnel à vérifier et utiliser', 'Diffusion à écarter'], [('Rapport utile au responsable sécurité habilité',0),('Nom du patient transmis à un ami',1),('Capture sur messagerie personnelle d’un collègue extérieur au site',1),('Signalement du document exposé au service compétent',0)], 'Le destinataire, la finalité et le canal comptent ensemble. Être collègue n’est pas une habilitation universelle.'),
     associate('Reliez les précautions à leur but.', [('Limiter le rapport aux faits utiles','Minimisation'),('Vérifier le destinataire','Besoin d’en connaître'),('Utiliser le canal professionnel','Protection de la transmission'),('Protéger le document visible','Prévention d’une divulgation')], 'La confidentialité se construit à chaque étape, pas seulement au moment d’envoyer le rapport.'),
     choice('Que répondre à l’ami ?', 'Ne pas communiquer l’identité et rappeler le caractère professionnel de ces informations.', ['Donner seulement le nom, sans le diagnostic.', 'Partager la capture puis demander de l’effacer.'], 'L’identité seule peut déjà révéler une information personnelle ; une promesse d’effacement ne corrige pas la divulgation.'),
     sequence('Traitez le document laissé visible.', ['Empêcher sa consultation indue sans l’exploiter', 'Alerter le service responsable', 'Le remettre ou le sécuriser selon la procédure', 'Tracer le signalement si la procédure le prévoit'], 'On protège l’information sans créer de copie personnelle ni lire les détails inutiles.'),
     choice('Le responsable demande un fait utile figurant dans la main courante. La discrétion impose-t-elle le silence ?', 'Non, la transmission professionnelle habilitée reste nécessaire.', ['Oui, toute information doit rester avec l’agent.', 'Non, on peut alors diffuser le registre complet à toute l’équipe.'], 'La discrétion n’est ni une rétention systématique ni une diffusion générale.')])

dossier('06-03', 'Préparer un contrôle sans maquiller les écarts',
    "Coopérer à un contrôle exige de vérifier la qualité des intervenants et de faciliter l’accès aux éléments demandés dans le cadre de leurs pouvoirs. L’agent informe sa hiérarchie et suit le circuit prévu, sans obstruction ni remise de données à un faux contrôleur.\n\nUne pièce manquante se signale comme telle. Modifier rétroactivement un planning, masquer un incident ou prêter son titre à un collègue n’est pas une préparation acceptable. L’objectif est de rendre la situation compréhensible : documents disponibles, détenteur des pièces manquantes et écarts constatés. La régularisation éventuelle doit rester distincte de la réalité passée.",
    [('Arrivée au poste', 'Deux personnes se présentent pour un contrôle administratif. Elles annoncent leur service et peuvent justifier leur qualité. Le responsable d’exploitation est joignable.'),
     ('Documents du poste', 'Le planning du jour et les consignes sont disponibles. Une pièce relative à un remplaçant est détenue par l’administration. Une erreur de nom apparaît sur un ancien planning conservé.'),
     ('Suggestion d’un collègue', 'Le collègue propose de réimprimer l’ancien planning avec le bon nom et de jeter l’original avant de le montrer. Le service administratif peut expliquer l’erreur et fournir les documents réellement disponibles.')],
    [classify('Classez les actions proposées.', ['Coopération traçable', 'À écarter'], [('Vérifier la qualité des intervenants selon la procédure',0),('Détruire le planning comportant l’erreur',1),('Signaler la pièce détenue par l’administration',0),('Présenter une correction comme si elle était le document d’origine',1)], 'Coopérer ne signifie pas falsifier. Une correction doit être datée et identifiable selon les procédures applicables.'),
     associate('Qui ou quoi permet de répondre ?', [('Qualité des intervenants','Justificatifs et vérification du contrôle'),('Pièce du remplaçant','Service administratif détenteur'),('Organisation du site','Responsable d’exploitation'),('Erreur historique','Original conservé et explication documentée')], 'La bonne réponse est parfois d’identifier le détenteur d’une pièce, sans inventer son contenu.'),
     choice('Comment présenter l’erreur de nom ?', 'La signaler, conserver l’original et joindre l’explication ou la correction traçable disponible.', ['La corriger discrètement sur tous les exemplaires.', 'Accuser immédiatement le remplaçant.'], 'La transparence permet d’examiner l’écart sans altérer les éléments.'),
     sequence('Accueillez les intervenants.', ['Vérifier leur qualité dans le cadre prévu', 'Informer le responsable et organiser l’accueil', 'Présenter les éléments disponibles et signaler les manques', 'Tracer les demandes et les suites données'], 'L’information de la hiérarchie ne doit pas servir à retarder ou empêcher un contrôle légitime.'),
     choice('Un appel extérieur demande ensuite l’envoi de tous les titres sur une adresse inconnue. Que faire ?', 'Faire vérifier l’authenticité de la demande et le canal avant transmission.', ['Envoyer les pièces car un contrôle a eu lieu.', 'Refuser définitivement toute coopération future.'], 'Un contrôle réel n’authentifie pas automatiquement toute demande reçue ensuite.')])

dossier('06-04', 'Refuser une consigne, assurer la continuité',
    "Une instruction hiérarchique doit être examinée au regard de sa légalité et des limites de mission. Le refus d’un acte interdit ne dispense pas de traiter le besoin légitime de sécurité qui a motivé la demande. Expliquez l’écart, sollicitez l’encadrement et proposez une mesure compatible avec vos pouvoirs.\n\nLa traçabilité doit distinguer la demande reçue, votre réponse, les mesures maintenues et le relais obtenu. Elle évite qu’un refus soit interprété comme un abandon du poste. Si le danger évolue, la protection et l’alerte deviennent prioritaires. La loyauté professionnelle ne consiste pas à obéir à toute demande ; elle consiste à exercer correctement la mission.",
    [('Consigne au dépôt', 'Le contrôle concerne l’accès au dépôt et les livraisons autorisées. Une procédure prévoit d’appeler le responsable pour les litiges avec les transporteurs.'),
     ('Demande du chef de quai', 'Après un désaccord commercial, le chef de quai demande de retenir le conducteur dans un bureau jusqu’au paiement d’une facture. Le conducteur est calme et souhaite partir.'),
     ('Moyens de continuité', 'L’agent peut maintenir le contrôle du portail sans enfermer personne. Le responsable d’exploitation et le service commercial sont joignables. Aucun fait décrit ne relève d’une interpellation en flagrance.')],
    [classify('Distinguez les réponses possibles.', ['Mesure professionnelle adaptée', 'Contrainte injustifiée dans ce cas'], [('Maintenir le contrôle d’accès du dépôt',0),('Enfermer le conducteur pour obtenir un paiement',1),('Orienter le litige vers le service commercial',0),('Retenir ses documents comme garantie',1)], 'Une dette commerciale ne crée pas pour l’agent un pouvoir de rétention des personnes ou de leurs documents.'),
     associate('Reliez chaque action à son objectif.', [('Expliquer la limite de pouvoir','Éviter l’acte interdit'),('Joindre le responsable','Faire arbitrer la consigne'),('Maintenir la surveillance du portail','Assurer la continuité'),('Noter demande et réponse','Rendre la décision traçable')], 'Le refus doit s’accompagner d’une réponse au besoin légitime qui reste dans le périmètre de mission.'),
     choice('Quelle phrase exprime le refus sans abandon ?', '« Je ne peux pas retenir une personne pour cette facture ; je contacte le responsable et maintiens le contrôle du dépôt. »', ['« Votre demande me déplaît, je quitte le poste. »', '« Je le retiens seulement dix minutes. »'], 'Réduire la durée d’une contrainte injustifiée ne la rend pas légale.'),
     sequence('Organisez la suite du litige.', ['Écarter la rétention demandée et préserver une situation calme', 'Saisir le responsable d’exploitation', 'Assurer le relais commercial et la surveillance', 'Tracer les faits et la décision confirmée'], 'La chaîne de traitement évite de confondre recouvrement commercial et sécurité privée.'),
     choice('Le chef de quai insiste en signant un ordre. Qu’est-ce qui change ?', 'La demande devient documentée, mais l’acte demandé reste à écarter.', ['La signature transfère toute responsabilité à son auteur.', 'La signature autorise une courte rétention.'], 'Un écrit ne crée pas un pouvoir absent du cadre légal.')])

dossier('07-01', 'Une attente qui se transforme en tension',
    "Un conflit se prépare souvent avant les insultes. Repérez les changements de voix, de rythme, de gestes, de distance et de comportement du groupe. Un signe isolé ne suffit pas à prédire une violence : il faut comparer l’évolution et le contexte. Une personne peut parler fort parce qu’elle entend mal ou parce que l’environnement est bruyant.\n\nL’agent agit sur ce qu’il peut clarifier : raison de l’attente, information disponible, circuit de résolution et possibilité de patienter sans bloquer les autres. Une explication honnête vaut mieux qu’une promesse de délai inventée. Surveillez en parallèle les voies de sortie, la position des tiers et la possibilité d’appeler un collègue.",
    [('Hall d’un centre d’examens', 'Le contrôle des convocations est interrompu par une panne. Douze personnes attendent depuis vingt minutes. L’agent n’a reçu aucun délai de remise en service.'),
     ('Évolution observée', 'Un candidat qui attendait en silence répète sa demande, hausse le ton et avance vers le bureau. Deux autres reprennent ses paroles. Personne n’a porté de coup ni proféré de menace explicite.'),
     ('Moyens disponibles', 'Un responsable peut donner un point de situation. Une zone d’attente est libre. Un collègue peut maintenir le passage de sortie pendant que l’agent échange avec le candidat.')],
    [classify('Distinguez observation et interprétation.', ['Signe observé', 'Interprétation à ne pas affirmer'], [('La voix devient plus forte qu’au début',0),('Le candidat veut nécessairement frapper',1),('Deux personnes reprennent ses paroles',0),('Tous les candidats sont dangereux',1)], 'Le changement de comportement est utile ; une intention supposée ne doit pas être présentée comme un fait.'),
     associate('Quel levier répond à quel problème ?', [('Délai inconnu','Demander une information fiable'),('Sortie encombrée','Maintenir un passage libre'),('Candidat qui se rapproche','Adapter la distance et la posture'),('Mécontentement qui se diffuse','Informer clairement le groupe')], 'Le traitement du conflit porte aussi sur l’environnement, pas seulement sur les mots.'),
     choice('Quelle annonce évite une promesse incontrôlée ?', '« Je demande un point au responsable et je vous communique ce qui est confirmé. »', ['« Tout repartira dans deux minutes. »', '« Attendez sans poser de questions. »'], 'Un délai inventé risque d’aggraver la tension lorsqu’il n’est pas tenu.'),
     sequence('Préparez une réponse à cette montée de tension.', ['Observer l’évolution et préserver l’espace de sécurité', 'Reconnaître la difficulté et écouter la demande', 'Obtenir puis transmettre une information confirmée', 'Réévaluer le groupe et demander un relais si nécessaire'], 'Cette démarche ne suppose pas que le conflit soit déjà violent ; elle permet une intervention précoce.'),
     choice('Le candidat baisse le ton après l’explication. Que faire ?', 'Poursuivre l’information et surveiller l’évolution sans maintenir une posture de confrontation.', ['Le traiter comme une menace acquise.', 'Annoncer que tout risque a disparu définitivement.'], 'L’évaluation doit suivre les faits dans les deux sens, aggravation comme apaisement.')])

dossier('07-02', 'Reformuler sans promettre ce qu’on ne peut donner',
    "Écouter ne signifie pas accepter la demande. Une reformulation distingue le problème exprimé, son effet pour la personne et ce qui peut être vérifié. Elle permet de corriger un malentendu avant de rappeler la règle. Évitez de répéter mécaniquement la dernière phrase ou d’ajouter un jugement.\n\nL’agent peut reconnaître une difficulté sans reconnaître une faute qu’il n’a pas constatée. Il propose ensuite une action concrète dans sa marge de manœuvre. Une question courte et précise aide davantage qu’une suite de questions à tonalité d’interrogatoire. L’accord porte sur la prochaine étape, pas sur une promesse de résultat.",
    [('Accueil d’un laboratoire', 'Une visiteuse affirme avoir un rendez-vous à 09 h. Son nom ne figure pas sur la liste transmise à l’agent. Elle dit avoir déjà appelé deux fois sans réponse.'),
     ('Échange', 'Elle déclare : « Vous me faites perdre ma journée, personne ne m’écoute. » L’agent peut appeler le secrétariat avec son accord et dispose d’un espace d’attente.'),
     ('Limite du poste', 'L’agent ne peut ni créer le rendez-vous ni autoriser seul l’accès au laboratoire. Le secrétariat est chargé de confirmer l’heure et le service concernés.')],
    [classify('Classez les formulations.', ['Écoute et clarification', 'Jugement ou promesse sans fondement'], [('« Vous indiquez un rendez-vous à 09 h et vous souhaitez le faire confirmer. »',0),('« Vous avez sûrement mal lu votre message. »',1),('« Je vais appeler le secrétariat pour vérifier. »',0),('« Vous serez reçue, quoi qu’indique la liste. »',1)], 'Reformuler rapporte la demande sans accuser ni promettre l’issue.'),
     associate('À quoi sert chaque phrase ?', [('« Quel service vous attend ? »','Préciser l’information utile'),('« L’attente complique votre organisation. »','Reconnaître la difficulté'),('« Je contacte le secrétariat. »','Proposer une action réalisable'),('« L’accès sera confirmé par le service. »','Expliquer la limite de décision')], 'Ces fonctions se complètent sans donner à l’agent un pouvoir d’admission supplémentaire.'),
     choice('Quelle reformulation doit être évitée ?', '« Vous êtes en colère parce que vous avez oublié votre rendez-vous. »', ['« Vous souhaitez savoir si le service peut vous recevoir. »', '« Vous dites avoir appelé deux fois. »'], 'La première phrase invente une cause et peut être vécue comme une accusation.'),
     sequence('Organisez l’échange.', ['Laisser la personne exposer la difficulté', 'Reformuler et vérifier la compréhension', 'Expliquer la vérification possible et la limite du poste', 'Confirmer avec elle la prochaine étape'], 'Une reformulation utile ouvre une action ; elle ne sert pas à gagner du temps sans traiter le besoin.'),
     choice('Le secrétariat confirme un rendez-vous à 10 h. Comment transmettre ?', 'Donner l’information confirmée et les possibilités d’attente ou de retour prévues.', ['Insister sur le fait que la visiteuse avait tort.', 'Modifier soi-même l’horaire pour apaiser.'], 'L’objectif est de résoudre la difficulté avec une information fiable et une option praticable.')])

dossier('07-03', 'La posture dans un couloir étroit',
    "Une posture de sécurité combine disponibilité, visibilité des mains, distance adaptée et possibilité de retrait. Il n’existe pas une distance magique valable partout : la configuration, les mouvements et la présence de tiers imposent de réévaluer. Se coller à une personne ou lui barrer toute issue peut accroître la tension.\n\nPréparer un relais ne consiste pas à entourer la personne. Les collègues doivent savoir qui parle et qui maintient l’environnement sûr. Le ton, le débit et le positionnement doivent rester cohérents. Une parole apaisante accompagnée d’un geste brusque transmet un message contradictoire.",
    [('Plan du couloir d’une résidence', 'Le passage mesure environ deux mètres de large. Une porte latérale mène au hall ouvert. Un chariot réduit le passage près du bureau ; des résidents circulent derrière l’agent.'),
     ('Situation', 'Un visiteur conteste son refus d’accès. Il fait de grands gestes et se rapproche à chaque réponse. Il n’a pas d’objet menaçant visible. L’agent dispose d’une radio.'),
     ('Renfort', 'Un collègue arrive par le hall. Il peut écarter les tiers et libérer le passage. Le responsable est disponible pour reprendre la discussion si elle ne s’apaise pas.')],
    [classify('Quels choix améliorent l’espace de sécurité ?', ['Améliore la situation', 'Risque d’aggraver'], [('Conserver une possibilité de retrait vers le hall',0),('Se placer dos au chariot sans issue',1),('Faire maintenir les tiers à distance par le collègue',0),('Entourer le visiteur à deux pour le convaincre',1)], 'Le positionnement doit protéger sans devenir une manœuvre d’intimidation.'),
     associate('Répartissez les fonctions.', [('Agent qui échange','Parole principale et observation de la personne'),('Collègue de renfort','Protection du passage et des tiers'),('Responsable','Relais de décision'),('Radio','Demande d’aide et transmission claire')], 'Des rôles clairs évitent que plusieurs personnes parlent simultanément ou ferment involontairement les issues.'),
     choice('Quelle demande associe calme et sécurité ?', '« Restons ici avec un peu d’espace pour pouvoir échanger et laisser passer les résidents. »', ['« Approchez encore si vous voulez être entendu. »', '« Mon collègue va vous empêcher de bouger. »'], 'La demande explique l’utilité de l’espace sans menace.'),
     sequence('Ajustez la posture lorsque le visiteur se rapproche.', ['Repérer la réduction de distance et les obstacles', 'Se repositionner sans geste brusque en gardant une issue', 'Demander calmement de conserver de l’espace', 'Solliciter le relais si le rapprochement ou la menace persiste'], 'La sécurité se prépare avant d’être coincé ; la réévaluation accompagne l’échange.'),
     choice('Le visiteur recule mais un groupe s’approche derrière l’agent. Que faut-il revoir ?', 'La position des tiers et la possibilité de retrait, même si l’échange s’apaise.', ['Rien, seul le visiteur compte.', 'Il faut immédiatement encercler le groupe.'], 'L’environnement reste une composante de la sécurité, indépendante de la baisse de tension verbale.')])

dossier('07-04', 'Insultes, menace et retrait',
    "Une insulte est une atteinte verbale à traiter professionnellement ; elle ne justifie pas une riposte de même nature ni une contrainte punitive. Une menace ou un comportement dangereux exige une évaluation distincte. Évitez de confondre ce qui blesse personnellement avec ce qui annonce un danger immédiat.\n\nPoser une limite consiste à nommer le comportement et à expliquer la suite possible : poursuivre calmement, faire intervenir le responsable, se mettre en sécurité ou alerter. Le retrait peut être une décision professionnelle lorsque l’échange devient dangereux. Il doit préserver les tiers et s’accompagner du relais adapté.",
    [('Entrée d’une salle de sport', 'Un usager dont l’abonnement est expiré insulte l’agent. Il reste d’abord à distance du comptoir. La procédure prévoit un relais vers l’accueil commercial pour les abonnements.'),
     ('Aggravation', 'L’usager frappe le comptoir avec sa main puis contourne le mobilier en annonçant qu’il va frapper l’agent. Deux clients sont proches du passage.'),
     ('Moyens', 'Une porte permet de se mettre en sécurité sans enfermer l’usager. Un collègue peut écarter les clients et appeler les secours ou les forces de l’ordre selon la situation.')],
    [classify('Distinguez les éléments.', ['Expression insultante', 'Élément de danger à réévaluer', 'Réponse professionnelle'], [('Propos injurieux à distance',0),('Menace de frapper accompagnée d’un contournement',1),('Demander un relais et protéger les clients',2),('Coup porté sur le comptoir',1)], 'Le contexte et l’évolution donnent sens aux signes ; la menace accompagnée d’un mouvement appelle une réaction de sécurité.'),
     associate('Reliez la phase à la priorité.', [('Litige d’abonnement','Relais commercial'),('Insultes sans rapprochement','Limite verbale et évaluation'),('Menace et approche','Mise en sécurité et alerte'),('Fin de l’événement','Compte rendu factuel')], 'Une même réponse ne convient pas à toutes les phases.'),
     choice('Quelle limite verbale reste professionnelle ?', '« Je peux poursuivre l’échange si nous restons calmes ; je fais venir le responsable. »', ['« Répétez cela et vous verrez. »', '« Vous êtes toujours comme ça, les gens comme vous. »'], 'La phrase porte sur le comportement et une solution, sans défi ni généralisation.'),
     sequence('À l’aggravation, organisez la réponse.', ['Repérer menace, mouvement et personnes exposées', 'Se mettre en sécurité et éloigner les tiers si possible', 'Donner l’alerte adaptée avec localisation et faits', 'Maintenir l’observation à distance et transmettre l’évolution'], 'Il ne s’agit pas d’attendre un coup pour se protéger, ni d’utiliser la force pour sanctionner une insulte.'),
     choice('L’usager part avant l’arrivée du renfort. Que transmettre ?', 'Le départ, la direction observée et les faits, sans inventer une poursuite nécessaire.', ['Une description exagérée pour garantir une intervention.', 'Aucun fait puisqu’il est parti.'], 'Le relais doit disposer de l’état actuel ; le départ n’efface pas les faits antérieurs.')])

dossier('07-05', 'Clore sans effacer les points à reprendre',
    "La fin d’un échange tendu ne signifie pas que tout est résolu. Distinguez l’apaisement immédiat, la décision sur le problème initial et les suites encore nécessaires. Une clôture utile confirme qui fait quoi et évite une nouvelle attente sans information.\n\nLe compte rendu retient les faits, les actions et leur résultat. Les qualificatifs comme agressif ou ingérable ne remplacent pas une description observable. Le retour d’expérience cherche ce qui a aidé ou aggravé : information tardive, passage encombré, plusieurs interlocuteurs, relais indisponible. Il ne sert pas à ridiculiser la personne ou à réécrire l’événement.",
    [('Fin d’un conflit à l’accueil d’un dépôt', 'Le conducteur a accepté d’attendre sur la zone prévue. Le responsable doit rappeler dans quinze minutes. L’erreur de numéro de livraison n’est pas encore résolue.'),
     ('Notes de l’agent', '14 h 10 : hausse du ton ; 14 h 12 : explication du contrôle ; 14 h 15 : appel au responsable ; 14 h 17 : accord sur l’attente. Aucun coup ni menace explicite n’a été constaté.'),
     ('Relève à 14 h 20', 'Le nouvel agent ne connaît pas l’accord. Le responsable n’a pas encore rappelé. La radio et le registre sont disponibles pour lui transmettre la situation.')],
    [classify('Quel est l’état de chaque point ?', ['Résolu à ce stade', 'Suite à assurer', 'Non établi'], [('Accord du conducteur sur une zone d’attente',0),('Confirmation du numéro de livraison',1),('Intention du conducteur de commettre une violence',2),('Rappel du responsable à surveiller',1)], 'Apaisement et résolution administrative sont deux résultats distincts.'),
     associate('Reliez les éléments à la relève.', [('Numéro à confirmer','Problème restant'),('Zone d’attente convenue','Mesure en cours'),('Responsable appelé à 14 h 15','Interlocuteur et heure'),('Rappel attendu','Prochaine action')], 'La relève a besoin d’une action à poursuivre, pas seulement du récit de la tension.'),
     choice('Quelle formulation de main courante est préférable ?', '« Hausse du ton à 14 h 10 ; accord d’attente à 14 h 17 après explication et appel au responsable. »', ['« Conducteur ingérable remis à sa place. »', '« Incident clos, plus aucune suite. »'], 'La première formule décrit une évolution observable et n’efface pas la vérification encore attendue.'),
     sequence('Clôturez votre prise en charge.', ['Confirmer l’accord et le point encore en attente', 'Informer la relève des faits et du prochain contact', 'Vérifier qu’elle a compris la suite à assurer', 'Consigner les éléments utiles et le relais effectué'], 'La boucle se ferme avec un relais compris, pas avec un simple départ du poste.'),
     choice('Le rappel n’arrive pas au délai annoncé. Que faire ?', 'Relancer par le circuit prévu et informer le conducteur de la situation réelle.', ['Attendre sans information pour éviter de rouvrir le conflit.', 'Annoncer un nouveau délai sans le vérifier.'], 'L’absence d’information peut recréer la tension ; il faut une mise à jour fiable.')])

dossier('08-01', 'Deux versions d’une consigne d’accès',
    "Une consigne exploitable précise le périmètre, le déclencheur, l’action attendue, les limites et le relais. Avant application, vérifiez sa version, sa date, son auteur et les éventuelles conditions temporaires. Une instruction connue de mémoire peut être devenue obsolète.\n\nEn cas de contradiction, il faut demander une clarification et maintenir les mesures sûres compatibles avec le cadre applicable. Ne choisissez pas simplement la consigne la plus stricte : elle peut bloquer une issue, retarder les secours ou dépasser vos pouvoirs. Une consigne générale et une instruction temporaire peuvent se compléter, à condition que leur articulation soit confirmée.",
    [('Consigne A · ancienne affiche', 'Fermer le portail secondaire à 18 h. Aucun nom de validateur n’apparaît. L’affiche est datée du mois précédent.'),
     ('Consigne B · travaux du jour', 'De 17 h à 20 h, le portail secondaire est l’accès prévu pour les secours pendant les travaux au portail principal. La consigne est validée par le responsable et transmise au poste.'),
     ('Situation à 17 h 55', 'Les travaux se poursuivent. Un collègue veut fermer le portail comme chaque soir. Le responsable peut confirmer le dispositif temporaire et les conditions de contrôle de cet accès.')],
    [classify('Quels éléments déterminent l’application ?', ['Élément utile à vérifier', 'Ne suffit pas seul'], [('Période 17 h–20 h de la consigne validée',0),('Habitude de fermer chaque soir',1),('Maintien des travaux à 17 h 55',0),('Affiche plus visible que le message récent',1)], 'La visibilité matérielle d’un document ne lui donne pas priorité sur une consigne validée applicable.'),
     associate('Repérez les composantes de la consigne B.', [('Portail secondaire','Périmètre'),('Travaux de 17 h à 20 h','Condition et période'),('Accès secours maintenu','Finalité opérationnelle'),('Responsable validateur','Interlocuteur de clarification')], 'Décomposer la consigne aide à voir ce qui reste inconnu, notamment les modalités concrètes de contrôle.'),
     choice('Quelle action convient à 17 h 55 ?', 'Faire confirmer le dispositif temporaire et préserver l’accès secours prévu.', ['Fermer automatiquement à 18 h par habitude.', 'Laisser entrer tout le monde car le portail sert aux secours.'], 'Maintenir un accès pour les secours ne supprime pas tout contrôle des autres accès.'),
     sequence('Traitez la contradiction documentaire.', ['Comparer versions, dates et périmètres', 'Identifier le risque d’une fermeture inadaptée', 'Obtenir la confirmation du responsable', 'Transmettre la règle confirmée à la relève et signaler l’affiche obsolète'], 'Le signalement documentaire évite que le prochain agent reproduise l’erreur.'),
     choice('Les travaux se terminent à 18 h 30. Peut-on modifier seul le dispositif ?', 'Il faut faire confirmer la fin du dispositif temporaire par le circuit prévu.', ['Oui, toute observation remplace la validation prévue.', 'Non, la consigne temporaire s’applique pour toujours.'], 'L’évolution des faits appelle une mise à jour confirmée, ni improvisation ni maintien indéfini.')])

dossier('08-02', 'Une alerte radio qui peut être comprise',
    "Un message opérationnel doit permettre au destinataire d’identifier l’émetteur, le lieu, le fait, le risque, l’action en cours et l’aide demandée. Sa brièveté ne doit pas supprimer les données qui orientent l’intervention. Employez les appellations de site connues plutôt que des repères ambigus comme derrière ou là-bas.\n\nLa transmission est une boucle : émission, réception, reformulation si nécessaire et confirmation. Une radio qui émet ne garantit pas que le message a été entendu. Sur un canal partagé, limitez les données personnelles et les détails sans utilité. Si le canal ne fonctionne pas, appliquez le moyen de secours prévu.",
    [('Plan d’un parc d’activités', 'Les accès sont nommés Nord N1, Est E2 et Sud S3. Le portail E2 donne sur l’atelier B. Le poste central utilise l’indicatif PC ; l’agent en ronde, R2.'),
     ('Observation à 10 h 42', 'R2 constate un portail E2 bloqué en position ouverte. Aucun blessé ni intrusion observée. L’agent maintient une surveillance depuis un point sûr et demande un renfort pour contrôler l’accès.'),
     ('Retour radio', 'Le PC répond : « Reçu, portail S3, intervention technique seule. » La liaison reste audible. Un téléphone de secours est disponible si la radio tombe en panne.')],
    [classify('Quels éléments doivent figurer dans l’alerte initiale ?', ['Utile immédiatement', 'À ne pas inventer'], [('Portail E2, atelier B',0),('Portail bloqué ouvert à 10 h 42',0),('Intrusion certaine',1),('Renfort demandé pour le contrôle d’accès',0)], 'Le message décrit le défaut et le besoin sans transformer une possibilité en intrusion constatée.'),
     associate('Associez les éléments de message.', [('R2 à PC','Émetteur et destinataire'),('E2, atelier B','Localisation'),('Bloqué ouvert, pas de blessé constaté','Faits et état observé'),('Renfort pour contrôle d’accès','Demande')], 'L’ordre facilite la compréhension, mais la priorité reste la clarté des données critiques.'),
     choice('Que faire de la réponse du PC ?', 'Corriger immédiatement E2 et le besoin de renfort, puis obtenir une confirmation exacte.', ['Considérer le message reçu puisque le PC a répondu.', 'Quitter le portail pour chercher le technicien.'], 'Le retour révèle deux erreurs ; la boucle n’est pas fermée tant qu’elles ne sont pas corrigées.'),
     sequence('Fermez la boucle radio.', ['Émettre le message factuel avec localisation', 'Écouter le retour du PC', 'Rectifier la localisation et le besoin mal compris', 'Faire confirmer la prise en compte exacte'], 'La confirmation protège contre une intervention envoyée au mauvais endroit.'),
     choice('La radio devient inaudible avant confirmation. Quelle suite ?', 'Utiliser le moyen de secours prévu et préciser que le premier message n’a pas été confirmé.', ['Répéter indéfiniment sur le canal défaillant.', 'Supposer que le PC a entendu la fin.'], 'Une absence de confirmation doit être traitée comme une incertitude opérationnelle.')])

dossier('08-03', 'Deux horloges et un événement à reconstruire',
    "Une chronologie utile distingue l’heure de l’événement, l’heure de sa connaissance et l’heure de saisie. Une note rédigée après coup ne doit pas présenter son horodatage comme celui des faits. Si deux dispositifs ne sont pas synchronisés, signalez l’écart au lieu de fabriquer une précision.\n\nLe compte rendu sépare observation personnelle, déclaration et trace technique. Une information peut être exacte sans avoir été observée par l’auteur. Attribuer la source permet au lecteur de comprendre la portée de chaque élément. Les corrections doivent rester traçables, en particulier lorsqu’une heure a été rectifiée.",
    [('Notes de ronde', 'L’agent note une porte ouverte à 21 h 12 sur sa montre. Il appelle le PC à 21 h 14. Il saisit le compte rendu à 21 h 25 après avoir sécurisé l’accès.'),
     ('Journal du système', 'Le système affiche une ouverture à 21 h 09. Le technicien indique que l’horloge du système peut avoir environ trois minutes de retard ; l’écart exact n’a pas été vérifié.'),
     ('Déclaration de la relève', 'Un collègue dit avoir vu un livreur près de la porte vers 21 h 10. Il n’a pas vu qui l’a ouverte. Aucun lien causal entre le livreur et l’ouverture n’est établi.')],
    [classify('Attribuez chaque élément à sa source.', ['Observation de l’agent', 'Trace technique', 'Déclaration de tiers'], [('Porte ouverte à 21 h 12 sur la montre',0),('Ouverture à 21 h 09 dans le système',1),('Livreur aperçu vers 21 h 10',2),('Décalage possible indiqué par le technicien',2)], 'La source doit accompagner l’information, surtout quand les heures ne concordent pas.'),
     associate('Distinguez les heures.', [('21 h 12 montre','Constat de l’agent'),('21 h 14','Appel au PC'),('21 h 25','Saisie du compte rendu'),('21 h 09 système','Horodatage technique à vérifier')], 'Ces quatre heures décrivent quatre événements ou références différents.'),
     choice('Comment rapprocher les deux horloges ?', 'Conserver les heures et leurs sources, signaler le décalage possible et demander vérification.', ['Corriger toutes les heures de trois minutes sans réserve.', 'Supprimer la trace qui contredit la montre.'], 'Un décalage approximatif ne permet pas une conversion exacte affirmée.'),
     sequence('Ordonnez les actions connues de l’agent.', ['Constat de la porte ouverte', 'Appel au PC', 'Sécurisation et suivi de l’accès', 'Saisie du compte rendu'], 'Le journal technique est une source parallèle ; il ne change pas l’ordre des actions personnellement réalisées.'),
     choice('Peut-on écrire que le livreur a ouvert la porte ?', 'Non, le collègue ne l’a pas vu et le lien n’est pas établi.', ['Oui, sa présence suffit.', 'Oui, si l’horodatage semble proche.'], 'La proximité temporelle n’est pas une preuve du geste ni de son auteur.')])

dossier('08-04', 'Une description exploitable, sans étiquette',
    "Décrire un incident consiste à choisir des détails utiles à l’action et à la compréhension : lieu, heure, gestes, paroles pertinentes, personnes exposées et mesures prises. Une accumulation de détails personnels ou de qualificatifs ne rend pas le récit plus précis.\n\nLa distinction entre fait et jugement s’applique aussi à l’état d’une personne. Une démarche instable ou une parole difficile se décrit sans conclure à une intoxication. Un malaise, une fatigue ou un autre problème peuvent produire des signes proches. Transmettez les signes utiles et demandez l’aide adaptée sans établir un diagnostic.",
    [('Incident dans un hall d’hôtel', 'À 23 h 06, une personne trébuche deux fois près de l’escalier, parle difficilement et s’assoit au sol. Elle répond à l’agent mais dit ne pas se sentir bien.'),
     ('Brouillon d’un collègue', '« Individu ivre et dangereux, probablement sans domicile ; évacué du hall. » Le collègue n’a pas vu de bouteille ni constaté de menace. Aucune évacuation n’a encore été réalisée.'),
     ('Actions réelles', 'L’agent écarte les passants de l’escalier et appelle le secours adapté depuis le poste. Il reste disponible, observe l’évolution et suit les instructions reçues.')],
    [classify('Quelles mentions sont étayées ?', ['Fait ou déclaration attribuable', 'Mention non établie'], [('Deux trébuchements observés',0),('Ivresse certaine',1),('La personne dit ne pas se sentir bien',0),('Évacuation déjà réalisée',1)], 'Les signes se décrivent ; les causes et actions non constatées ne s’inventent pas.'),
     associate('Reliez les données à leur utilité.', [('Près de l’escalier','Risque et localisation'),('23 h 06','Repère temporel'),('Répond mais parle difficilement','État observable à transmettre'),('Appel et instructions suivies','Actions réalisées')], 'Ces éléments aident les secours et la relève sans ajouter d’étiquette sociale.'),
     choice('Quelle première phrase convient ?', '« À 23 h 06, dans le hall près de l’escalier, une personne trébuche deux fois puis s’assoit au sol. »', ['« Un individu dangereux perturbe l’hôtel. »', '« Une personne alcoolisée simule un malaise. »'], 'La première phrase est vérifiable et ouvre une description précise de la suite.'),
     sequence('Construisez le récit.', ['Lieu, heure et faits observés', 'Paroles utiles attribuées à la personne', 'Mesures de protection et appel effectué', 'Évolution et relais aux intervenants'], 'Le lecteur doit pouvoir distinguer ce qui a été vu, dit et fait.'),
     choice('Le secours demande si la personne a consommé de l’alcool. Que répondre ?', 'Indiquer que cela n’a pas été constaté et décrire les signes observés.', ['Répondre oui pour aller plus vite.', 'Refuser de décrire les signes.'], 'Une réponse incertaine assumée est plus utile qu’un diagnostic inventé.')])

dossier('08-05', 'Une relève avec trois points ouverts',
    "Une relève doit transmettre les risques en cours, les mesures provisoires, les actions attendues et les contacts utiles. Le récit complet de la vacation ne doit pas masquer les priorités. Le nouvel agent doit savoir ce qu’il reprend, ce qu’il vérifie et à quel moment il relance.\n\nLa confirmation de compréhension est essentielle pour un point sensible. Faites reformuler la mesure provisoire et la prochaine action. Distinguez incident clos, incident surveillé et incident non résolu. Un équipement remis en service n’est déclaré opérationnel qu’après la confirmation prévue ; une promesse de passage du technicien ne vaut pas réparation.",
    [('État du poste à 06 h', 'Le portail Ouest reste fermé à la suite d’un défaut. Les accès passent par le portail Nord avec contrôle renforcé. Le technicien est attendu à 07 h ; aucune réparation n’est confirmée.'),
     ('Deux autres points', 'Une clé du local technique a été remise à un intervenant autorisé ; retour attendu à 06 h 30. Une alarme de porte a été vérifiée et close à 05 h 20 avec confirmation du responsable.'),
     ('Arrivée de la relève', 'Le nouvel agent connaît le site mais n’a pas lu le journal de nuit. Il pense que le portail Ouest est rouvert parce que le technicien a été appelé.')],
    [classify('Classez les points de relève.', ['À suivre', 'Clos avec confirmation'], [('Portail Ouest en défaut',0),('Retour de clé attendu à 06 h 30',0),('Alarme vérifiée et close à 05 h 20',1),('Intervention technique annoncée à 07 h',0)], 'Une demande d’intervention et une réparation effective sont deux états distincts.'),
     associate('Associez le point à sa prochaine action.', [('Portail Ouest','Maintenir le dispositif provisoire jusqu’à confirmation'),('Portail Nord','Poursuivre le contrôle renforcé prévu'),('Clé technique','Vérifier le retour à l’heure attendue'),('Technicien','Accueillir et obtenir le résultat de l’intervention')], 'La relève doit pouvoir agir sans reconstituer toute la nuit.'),
     choice('Quelle correction donner au nouvel agent ?', '« Le portail Ouest reste fermé ; l’appel technique n’est pas une remise en service. »', ['« Le technicien viendra donc tout est réglé. »', '« Vous lirez le journal quand vous aurez le temps. »'], 'Une incompréhension sur une mesure active doit être corrigée avant le départ de l’agent sortant.'),
     sequence('Effectuez la relève.', ['Présenter les risques et mesures encore actifs', 'Donner échéances et contacts', 'Faire reformuler les points sensibles', 'Tracer le relais et les éléments remis'], 'La confirmation transforme une information donnée en information comprise.'),
     choice('La clé n’est pas rendue à 06 h 30. Quelle suite ?', 'Appliquer la relance et le signalement prévus, en conservant l’identité du détenteur et l’heure attendue.', ['Clore le prêt parce que la vacation précédente est terminée.', 'Déclarer immédiatement un vol sans vérification.'], 'Le suivi porte d’abord sur les faits et le circuit de relance, sans qualification hâtive.')])

dossier('09-01', 'Justifier une réaction avec une chronologie',
    "Justifier une décision ne signifie pas trouver après coup une formule qui l’excuse. Il faut montrer le lien entre les faits disponibles au moment de l’action, le risque, les options possibles et la réponse effectivement choisie. L’analyse doit aussi identifier le moment où la justification évolue ou disparaît.\n\nUn rapport précis distingue les observations personnelles des éléments appris ensuite. Une vidéo découverte après l’événement peut éclairer l’analyse, mais ne doit pas être présentée comme une information dont l’agent disposait déjà. Reconnaître une limite de perception n’est pas une faiblesse du récit : c’est une condition de son exactitude.",
    [('Séquence observée', 'À 18 h 01, un individu lève une chaise vers un client. L’agent fait reculer le client et appelle du renfort. À 18 h 02, la chaise est posée et l’individu s’éloigne.'),
     ('Demande de rapport', 'Le responsable demande pourquoi l’agent n’a pas poursuivi l’individu. Un témoin évoque ensuite une dispute plus ancienne que l’agent n’a pas vue.'),
     ('Éléments disponibles au moment du choix', 'Une issue était libre derrière le client. Un collègue pouvait alerter. Aucune nouvelle menace n’a été observée après la chaise posée. La vidéo n’a été consultée qu’après le relais, par une personne habilitée.')],
    [classify('Quand l’information était-elle disponible ?', ['Pendant la décision', 'Apprise ensuite'], [('Chaise levée vers le client',0),('Dispute antérieure racontée par un témoin',1),('Issue libre derrière le client',0),('Contenu de la vidéo consultée après le relais',1)], 'Une justification honnête respecte la chronologie de l’information.'),
     associate('Reliez les faits au raisonnement.', [('Chaise levée','Atteinte à évaluer'),('Issue libre','Option de protection'),('Chaise posée et éloignement','Réévaluation de la nécessité'),('Appel de renfort','Relais organisé')], 'Le raisonnement lie les moyens à la menace actuelle, pas au désir de sanctionner.'),
     choice('Quelle justification de l’absence de poursuite est la plus solide ?', '« Après la chaise posée et l’éloignement, je n’observais plus de menace actuelle ; j’ai maintenu la protection et le relais. »', ['« Je savais grâce à la vidéo qu’il allait partir. »', '« Je ne poursuis jamais, quels que soient les faits. »'], 'La première réponse est située dans le cas et les informations réellement disponibles.'),
     sequence('Présentez l’analyse de décision.', ['Faits perçus au moment initial', 'Risque et options de protection', 'Action choisie et évolution observée', 'Arrêt ou adaptation de l’action et relais'], 'Cette structure aide à expliquer la nécessité et la proportionnalité sans masquer les changements.'),
     choice('La vidéo montre ensuite un détail non perçu. Comment l’ajouter ?', 'Comme un élément découvert après l’action, avec sa source.', ['Comme une observation personnelle initiale.', 'En modifiant silencieusement le premier récit.'], 'Les éléments nouveaux complètent le récit ; ils ne changent pas rétroactivement ce que l’agent savait.')])

dossier('09-02', 'Choisir l’aide qui protège vraiment',
    "Une décision d’assistance se justifie par le besoin de la personne et par les risques de l’environnement. L’agent doit expliquer pourquoi un geste était possible, pourquoi une autre action aurait été dangereuse et quel relais a été obtenu. La rapidité utile ne consiste pas à se précipiter sans observer.\n\nL’alerte, l’éloignement des tiers et l’accueil des secours sont des actions concrètes d’assistance. Lorsque le danger technique n’est pas maîtrisé, le rôle de l’agent est de préserver une zone sûre et de faire intervenir les personnes compétentes. Les instructions des secours guident la suite ; les limites de formation ne se compensent pas par une improvisation.",
    [('Incident sur un quai', 'Un salarié est au sol près d’un chariot immobilisé. Une fuite de produit inconnue est visible à proximité. L’agent reste à distance et n’a pas de protection adaptée au produit.'),
     ('Alerte et moyens', 'Le PC peut joindre les secours et le référent technique. Une voie d’accès sans traverser la fuite est disponible. Des collègues veulent déplacer la victime immédiatement.'),
     ('Informations manquantes', 'L’état exact de la victime, la nature du produit et la stabilité du chargement ne sont pas connus. Le référent détient les informations de sécurité sur le produit transporté.')],
    [classify('Distinguez l’action possible de l’exposition non maîtrisée.', ['Action depuis une zone sûre', 'Action à ne pas improviser'], [('Alerter avec localisation et dangers visibles',0),('Traverser la fuite pour déplacer immédiatement la victime',1),('Éloigner les collègues du périmètre',0),('Identifier le produit en le touchant',1)], 'La justification d’une limite doit être reliée aux dangers concrets, pas à une absence d’intérêt pour la victime.'),
     associate('Qui apporte quelle aide ?', [('Secours','Instructions et prise en charge de la victime'),('Référent technique','Informations sur le produit et le site'),('PC','Coordination de l’alerte et de l’accès'),('Agent','Protection du périmètre et observations')], 'Les rôles se complètent ; l’agent ne devient pas spécialiste du produit.'),
     choice('Quelle justification du non-déplacement est exacte ?', '« La fuite inconnue et le chargement rendent l’accès dangereux ; j’alerte et protège le périmètre. »', ['« Je ne fais rien tant que le responsable n’est pas là. »', '« Déplacer une victime est toujours interdit. »'], 'Une règle absolue serait inexacte. Ici, la décision découle du danger non maîtrisé et des moyens disponibles.'),
     sequence('Organisez l’assistance.', ['Repérer les dangers et rester en zone sûre', 'Alerter avec victime potentielle et risques', 'Empêcher les nouvelles expositions et préparer l’accès sûr', 'Suivre les instructions et transmettre l’évolution'], 'L’alerte ne doit pas attendre l’identification parfaite du produit.'),
     choice('Le produit est ensuite identifié par le référent. Que faire ?', 'Transmettre cette information aux secours et réévaluer uniquement dans le cadre des consignes reçues.', ['Considérer le danger disparu parce qu’il a un nom.', 'Entrer sans autre vérification.'], 'Identifier un produit ne prouve pas que la zone est sûre ni que l’agent est équipé pour y intervenir.')])

dossier('09-03', 'Expliquer pourquoi le consentement compte',
    "Il faut distinguer contrôle d’accès, inspection visuelle et fouille d’un bagage. Le consentement du propriétaire est requis pour la fouille dans le cadre de l’article L613-2. Une règle d’accès peut prévoir une conséquence au refus selon son cadre, mais ne crée pas un droit de fouille forcée.\n\nLes palpations relèvent de conditions spécifiques : le seul consentement ne suffit pas à autoriser toute pratique dans tout contexte. L’agent vérifie sa compétence, les autorisations et l’organisation applicables. Expliquer un refus exige de nommer la limite précise et le relais possible, sans présenter la personne comme suspecte du seul fait qu’elle exerce un droit.",
    [('Entrée d’une exposition', 'Le dispositif prévoit un contrôle des billets et une inspection visuelle des bagages. La consigne d’accès précise le recours au responsable en cas de refus du contrôle. Aucun dispositif de palpation n’est prévu pour l’agent de ce poste.'),
     ('Demande du responsable commercial', 'Il veut que l’agent ouvre lui-même le sac d’un visiteur qui refuse la fouille et lui impose une palpation, en invoquant le billet acheté.'),
     ('Situation du visiteur', 'Le visiteur ne menace personne. Il demande quelles alternatives existent et accepte de parler au responsable sécurité. Aucun fait d’infraction n’est observé.')],
    [classify('Quel fondement est présent ou absent ?', ['Élément réel du dispositif', 'Pouvoir non créé par le dossier'], [('Vérification du billet',0),('Fouille forcée par le seul achat du billet',1),('Relais au responsable en cas de refus',0),('Palpation improvisée au poste',1)], 'Le billet ne vaut pas renonciation générale aux droits. Le cadre précis de chaque contrôle doit être respecté.'),
     associate('Associez les questions à vérifier.', [('Fouille d’un bagage','Consentement du propriétaire et cadre applicable'),('Palpation','Conditions spécifiques, habilitations et consentement requis'),('Refus de contrôle','Procédure d’accès et relais'),('Suspicion d’infraction','Faits distincts à établir')], 'Ne fusionnez pas le refus d’un contrôle avec la preuve d’une infraction.'),
     choice('Quelle explication donner au responsable commercial ?', '« Le billet ne m’autorise pas à imposer cette fouille ou une palpation hors du dispositif ; je saisis le responsable sécurité. »', ['« Je peux tout contrôler si cela figure dans une consigne orale. »', '« Je dois laisser entrer immédiatement toute personne qui refuse. »'], 'La limite du pouvoir de fouille et la décision d’accès sont deux questions à traiter séparément dans leur cadre.'),
     sequence('Traitez la difficulté.', ['Expliquer le contrôle prévu et écouter le refus', 'Ne pas imposer la fouille ou une palpation non autorisée', 'Appliquer le relais et les options d’accès prévues', 'Tracer les faits utiles et la décision confirmée'], 'Le traitement reste calme et proportionné, sans qualifier automatiquement le visiteur de suspect.'),
     choice('Le visiteur consent finalement à une fouille du sac. Cela autorise-t-il aussi une palpation ?', 'Non, ce sont des actes distincts avec des conditions propres.', ['Oui, un consentement vaut pour tous les contrôles.', 'Oui, si le même agent les réalise.'], 'Il faut vérifier séparément le cadre et le consentement requis pour chaque acte.')])

dossier('10-01', 'Le danger existe, l’exposition change',
    "Le danger est une propriété ou une situation susceptible de causer un dommage ; le risque dépend notamment des conditions d’exposition. Une machine en mouvement peut rester dangereuse même si personne ne se trouve actuellement dans sa zone. Une barrière réduit l’exposition, mais un passage ouvert peut remettre les personnes en contact avec le danger.\n\nL’observation de l’agent doit donc relier source de danger, personnes exposées, circonstances et mesures existantes. Signaler seulement dangereux est insuffisant pour agir. Le compte rendu doit préciser ce qui a changé : protection retirée, circulation déplacée, obstacle, intervention ou nouvel usage. L’agent alerte et protège selon ses consignes sans se substituer au responsable de prévention.",
    [('Atelier de conditionnement', 'Un convoyeur fonctionne derrière une protection fixe. Un passage piéton est matérialisé à l’écart. L’agent n’a pas de mission d’intervention sur la machine.'),
     ('Changement pendant la ronde', 'Une protection a été retirée pour maintenance. Des cartons encombrent le passage piéton, et deux salariés contournent l’obstacle en passant près du convoyeur.'),
     ('Organisation', 'Le chef d’atelier est joignable. Une zone d’attente sûre existe en amont. La remise en état et l’autorisation de reprise relèvent des personnes compétentes du site.')],
    [classify('Distinguez les notions.', ['Danger', 'Exposition', 'Mesure de prévention'], [('Pièces mobiles du convoyeur',0),('Salariés qui passent près des pièces accessibles',1),('Protection fixe en place',2),('Cheminement piéton séparé',2)], 'Le risque se comprend en reliant le danger à une exposition réelle ou possible et aux protections présentes.'),
     associate('Quel constat faut-il transmettre ?', [('Protection retirée','Barrière physique absente'),('Cartons dans le cheminement','Cause du détour piéton'),('Convoyeur en fonctionnement','Énergie et mouvement présents'),('Salariés à proximité','Personnes exposées')], 'Ces informations permettent au responsable de traiter les causes, pas seulement d’écarter un piéton momentanément.'),
     choice('Quelle action relève du poste ?', 'Alerter le chef d’atelier et empêcher de nouvelles expositions depuis une zone sûre selon les consignes.', ['Remonter la protection pendant le fonctionnement.', 'Traverser la zone pour pousser les cartons.'], 'L’agent ne devient pas technicien de maintenance. La protection du périmètre ne doit pas l’exposer.'),
     sequence('Analysez le changement de situation.', ['Identifier la source de danger', 'Repérer qui est exposé et pourquoi', 'Signaler les protections manquantes et protéger l’accès', 'Obtenir le relais compétent et suivre la mesure confirmée'], 'L’analyse ne s’arrête pas au premier défaut visible ; l’obstacle contribue aussi à l’exposition.'),
     choice('Les salariés s’éloignent, mais la protection reste retirée. Peut-on déclarer le risque définitivement supprimé ?', 'Non, le danger et la possibilité d’une nouvelle exposition persistent.', ['Oui, l’absence momentanée de piétons suffit.', 'Oui, si un panneau est posé sans autre mesure.'], 'La reprise doit être confirmée dans le cadre prévu après traitement des causes.')])

dossier('10-02', 'Lire une évaluation sans confondre document et action',
    "Le document unique d’évaluation des risques professionnels organise l’identification et l’évaluation des risques. Il contribue à définir des actions de prévention, mais sa présence ne prouve pas que toutes les mesures sont appliquées sur le terrain. L’agent doit savoir rapprocher le document, les consignes de son poste et les observations réelles.\n\nUne modification de circulation, de produit ou d’activité peut rendre une mesure insuffisante. L’agent fait remonter les écarts avec des faits précis. Il ne modifie pas seul l’évaluation de l’employeur et ne déclare pas un site conforme sur la seule lecture d’une fiche. Il vérifie les mesures de son périmètre et identifie le responsable du traitement.",
    [('Extrait pédagogique d’évaluation', 'Risque de collision au quai : séparation piétons–engins, éclairage et contrôle des cheminements. Responsable de l’action : exploitation. La fiche concerne l’organisation habituelle du quai.'),
     ('Ronde à 05 h 30', 'Un éclairage est en panne. Une livraison exceptionnelle occupe le cheminement piéton et les salariés passent derrière les véhicules. Un panneau de séparation reste affiché.'),
     ('Consigne du poste', 'Signaler les défauts d’éclairage et de circulation au responsable. Ne pas pénétrer dans la zone de manœuvre pour déplacer soi-même les palettes. Une entrée piétonne alternative peut être ouverte sur décision de l’exploitation.')],
    [classify('Distinguez le prescrit et le constaté.', ['Mesure prévue', 'Écart observé'], [('Séparation piétons–engins',0),('Éclairage en panne',1),('Contrôle des cheminements',0),('Passage de salariés derrière les véhicules',1)], 'Le document décrit une organisation attendue ; la ronde vérifie sa réalité dans la situation du jour.'),
     associate('Quel relais pour chaque sujet ?', [('Évaluation et décision de prévention','Employeur et responsables compétents'),('Défaut constaté en ronde','Signalement précis par l’agent'),('Déplacement des palettes','Intervenants autorisés'),('Ouverture de l’entrée alternative','Décision de l’exploitation')], 'L’agent contribue à la prévention en tenant son rôle, sans improviser une opération de manutention.'),
     choice('Le panneau de séparation suffit-il à considérer la mesure appliquée ?', 'Non, le cheminement est obstrué et l’exposition est observée.', ['Oui, puisqu’il rappelle la règle.', 'Oui, si la livraison est exceptionnelle.'], 'Une mesure écrite ne compense pas automatiquement un obstacle réel.'),
     sequence('Préparez le signalement.', ['Localiser les défauts et les personnes exposées', 'Comparer avec les mesures prévues', 'Alerter l’exploitation et demander une solution sûre', 'Suivre et tracer la décision mise en œuvre'], 'Le signalement doit permettre une action et un suivi, pas seulement constater un écart.'),
     choice('La livraison se termine mais l’éclairage reste en panne. Que reste-t-il à suivre ?', 'Le défaut d’éclairage et la confirmation des mesures adaptées.', ['Rien, l’événement principal est terminé.', 'Seulement le retrait du panneau.'], 'Chaque cause doit être traitée ; la disparition d’un obstacle ne répare pas l’éclairage.')])

dossier('10-03', 'Deux entreprises, un risque d’interférence',
    "La coactivité crée des risques par l’interférence des travaux, des installations et des circulations. Une entreprise peut maîtriser sa propre tâche tout en ignorant l’activité voisine. La prévention suppose une coordination préalable et une actualisation lorsque les conditions changent.\n\nLes documents et autorisations doivent correspondre à l’intervention réelle : lieu, période, travaux, risques et mesures. Un plan annuel générique ne suffit pas à prouver qu’une nouvelle intervention a été examinée. L’agent contrôle ce qui lui est confié, signale les écarts et sollicite le coordinateur ; il ne valide pas lui-même un changement technique.",
    [('Intervention prévue', 'Une entreprise doit effectuer une maintenance dans l’atelier A de 08 h à 12 h. L’accueil sécurité et le périmètre d’intervention sont prévus avec le responsable du site.'),
     ('Changement annoncé', 'À l’arrivée, l’intervenant veut travailler dans l’atelier B avec un outil générant des étincelles. Une autre équipe y utilise des produits inflammables. Il présente le document annuel de son entreprise.'),
     ('Rôle du poste', 'Le contrôle d’accès vérifie l’entreprise attendue et contacte le responsable avant tout écart au périmètre. L’agent ne délivre pas les autorisations techniques et dispose d’une zone d’attente.')],
    [classify('Quels changements nécessitent une coordination ?', ['Changement pertinent', 'Ne valide pas le changement'], [('Atelier B au lieu de A',0),('Étincelles près de produits inflammables',0),('Document annuel présenté seul',1),('Présence de l’autre équipe',0)], 'Le risque vient du croisement des activités. Le document doit être confronté à la situation réelle.'),
     associate('Reliez les vérifications.', [('Entreprise et intervenants','Identité et accueil prévus'),('Atelier et créneau','Périmètre de l’intervention'),('Outil et produits voisins','Interférences dangereuses'),('Responsable du site','Coordination et confirmation des mesures')], 'L’autorisation d’accès d’une personne ne vaut pas autorisation de tout travail sur tout le site.'),
     choice('Que décider au contrôle ?', 'Maintenir l’intervention en attente et faire vérifier le changement par le responsable compétent.', ['Autoriser parce que l’entreprise est connue.', 'Remplacer soi-même le nom de l’atelier sur le document.'], 'Une modification documentaire improvisée ne remplace pas l’analyse du nouveau risque.'),
     sequence('Traitez l’écart.', ['Comparer intervention annoncée et intervention prévue', 'Repérer les interférences et éviter le démarrage non validé', 'Saisir le coordinateur avec les faits', 'Appliquer les conditions confirmées et tracer le relais'], 'Le contrôle prévient une exposition avant le commencement des travaux.'),
     choice('L’autre équipe annonce avoir terminé, mais les produits restent sur place. Le risque a-t-il automatiquement disparu ?', 'Non, le responsable doit vérifier la situation matérielle et les mesures nécessaires.', ['Oui, la fin de l’équipe supprime tous les risques.', 'Oui, si l’intervention dure moins de dix minutes.'], 'Les produits et l’atmosphère peuvent rester dangereux après la fin d’une tâche.')])

dossier('10-04', 'Se repérer avant une alerte industrielle',
    "Un plan de site sert à relier une observation à un accès, un bâtiment, une zone de risque et un interlocuteur. Une localisation claire doit pouvoir être comprise par un intervenant qui ne connaît pas les habitudes du poste. Les noms officiels des zones et les points d’accueil sont donc essentiels.\n\nEn cas d’incident, le trajet le plus court n’est pas toujours le plus sûr. Vérifiez les zones interdites, les circulations d’engins et les consignes temporaires. L’agent n’explore pas une zone dangereuse pour préciser une information : il transmet ce qu’il sait depuis un point sûr et signale les limites de son observation.",
    [('Plan simplifié du site Argile', 'Portail P1 : accueil habituel. Portail P3 : accès secours. Bâtiment C : stockage. Bâtiment D : maintenance. Une voie engins sépare C et D ; les piétons utilisent le passage balisé au Nord.'),
     ('Consigne temporaire', 'P1 est fermé pour travaux. Les secours sont accueillis à P3. Le passage Sud est interdit en raison d’une opération de levage. La consigne est confirmée pour la vacation.'),
     ('Observation', 'Depuis le passage Nord, l’agent voit un dégagement inhabituel près de C, sans en connaître l’origine. Aucun blessé n’est visible. Il peut alerter sans traverser la voie engins.')],
    [classify('Quels déplacements sont compatibles avec le dossier ?', ['Cheminement ou position prévu', 'À éviter'], [('Rester au passage Nord pour alerter',0),('Couper par le levage au Sud',1),('Préparer l’accueil à P3',0),('Traverser la voie engins pour mieux voir',1)], 'Une précision supplémentaire ne justifie pas une exposition inutile.'),
     associate('Associez les repères.', [('P3','Accès secours confirmé'),('C','Zone de stockage concernée'),('Nord','Passage piéton balisé'),('Sud','Zone interdite pour levage')], 'Les noms exacts permettent d’éviter un guidage vers une entrée fermée ou une zone dangereuse.'),
     choice('Quelle localisation transmettre ?', '« Dégagement inhabituel près du bâtiment C, observé depuis le passage Nord ; accueil secours prévu à P3. »', ['« De la fumée derrière le hangar, venez à l’entrée habituelle. »', '« Incident en D », car D est le bâtiment le plus proche du PC.'], 'Le message sépare lieu du phénomène, point d’observation et accès des intervenants.'),
     sequence('Préparez l’arrivée des intervenants.', ['Alerter avec les repères confirmés', 'Informer le poste de l’accès P3 et des interdictions temporaires', 'Organiser un accueil par une personne disponible en sécurité', 'Transmettre toute évolution sans entrer dans la zone'], 'L’accueil fait partie de l’alerte opérationnelle ; il ne doit pas exposer l’agent.'),
     choice('Un chauffeur suggère P1 parce qu’il connaît mieux cette entrée. Que répondre ?', 'Rappeler la fermeture confirmée et orienter selon le dispositif prévu.', ['Le laisser choisir pour gagner du temps.', 'Ouvrir P1 sans consulter les consignes.'], 'La connaissance habituelle du site ne remplace pas la configuration du jour.')])

dossier('10-05', 'Un équipement ne remplace pas la prévention',
    "La prévention privilégie l’élimination ou la réduction du danger et les protections collectives avant le recours aux équipements de protection individuelle. Un EPI se choisit pour un risque, une tâche et un utilisateur ; sa présence ne rend pas toute intervention possible. Il faut aussi vérifier son état, ses limites et la formation nécessaire.\n\nL’agent applique les équipements prévus pour sa mission sans improviser une protection technique. Des gants courants, un gilet ou un masque non identifié ne protègent pas de tous les risques. Une zone interdite reste interdite jusqu’à décision compétente, même si une personne pense être suffisamment équipée.",
    [('Zone de livraison', 'Le site prévoit un cheminement séparé des engins et un gilet de visibilité pour les agents affectés à l’accueil des chauffeurs. Le gilet ne protège pas d’un choc avec un véhicule.'),
     ('Écart constaté', 'Une barrière du cheminement est déplacée. Un collègue veut continuer à faire traverser les visiteurs entre les engins en leur donnant un gilet.'),
     ('Autre demande', 'Un bidon fuit près du quai. Des gants de manutention sont disponibles, mais aucun équipement ni mission de traitement de fuite chimique n’est prévu pour l’agent. Le référent technique peut intervenir.')],
    [classify('Distinguez les types de mesures.', ['Protection collective ou organisationnelle', 'Équipement individuel', 'Substitution insuffisante'], [('Séparation du cheminement et des engins',0),('Gilet de visibilité prévu',1),('Gilet utilisé pour remplacer une séparation absente',2),('Gants courants pour traiter un produit inconnu',2)], 'Un équipement utile dans une tâche ne couvre pas automatiquement une autre exposition.'),
     associate('Que faut-il vérifier ?', [('Barrière déplacée','Continuité du cheminement sûr'),('Gilet','Visibilité, état et usage prévu'),('Gants de manutention','Limites de protection'),('Fuite inconnue','Relais technique et périmètre sûr')], 'Le choix d’une mesure dépend du risque réel et du rôle de l’agent.'),
     choice('Quelle suite donner pour les visiteurs ?', 'Faire rétablir ou confirmer un cheminement sûr avant le passage, selon le responsable.', ['Maintenir le passage entre engins grâce aux gilets.', 'Demander aux visiteurs de courir.'], 'La visibilité ne supprime ni la masse ni les angles morts d’un engin.'),
     sequence('Analysez une demande d’équipement.', ['Identifier le risque et la tâche', 'Vérifier les mesures collectives et l’organisation', 'Contrôler l’équipement prévu, ses limites et les compétences', 'Alerter si les conditions ne sont pas réunies'], 'L’équipement vient dans une démarche de prévention, pas comme réponse unique à tout défaut.'),
     choice('Le bidon porte un pictogramme lisible. Les gants courants deviennent-ils adaptés ?', 'Non, il faut les protections déterminées pour le produit et l’intervention par les personnes compétentes.', ['Oui, voir le pictogramme suffit.', 'Oui, si la fuite paraît petite.'], 'La taille apparente de la fuite et la présence d’une étiquette ne valident pas l’équipement disponible.')])

dossier('10-06', 'Lire une étiquette avec sa fiche de sécurité',
    "L’étiquette signale les dangers principaux d’un produit ; la fiche de données de sécurité fournit des informations complémentaires sur les protections et les mesures d’urgence. Il faut vérifier que la fiche correspond au produit réel, à son identification et à sa version. Un produit transvasé dans un contenant mal identifié crée une incertitude à signaler.\n\nNe cherchez pas à reconnaître un produit en le sentant, le touchant ou le mélangeant. Les informations documentaires se consultent depuis une zone sûre et se transmettent aux intervenants. Le rôle de l’agent est d’alerter et de protéger selon les consignes, pas de choisir seul une méthode de neutralisation chimique.",
    [('Étiquette pédagogique', 'Un bidon est identifié « Nettoyant K ». L’étiquette signale des dangers et renvoie aux conseils de prudence. Le contenant est abîmé ; un écoulement est visible au sol.'),
     ('Deux fiches disponibles', 'Le dossier contient une fiche « Nettoyant J » et une fiche « Nettoyant K ». Les références commerciales diffèrent. Le responsable technique peut vérifier la fiche correspondant au lot présent.'),
     ('Situation de ronde', 'Personne n’est signalé en contact avec le liquide. Un salarié propose d’essuyer avec un chiffon puis de rincer. L’agent peut empêcher l’accès à distance et transmettre l’identification lue sans s’approcher davantage.')],
    [classify('Quels gestes préservent la sécurité ?', ['Démarche adaptée', 'Manipulation à ne pas improviser'], [('Transmettre l’identification visible',0),('Sentir le produit pour confirmer son nom',1),('Faire vérifier la fiche correspondante',0),('Rincer ou mélanger sans procédure adaptée',1)], 'Les gestes d’identification ou de nettoyage peuvent exposer ou provoquer une réaction ; ils relèvent d’une procédure et de personnels compétents.'),
     associate('Associez les supports à leur rôle.', [('Étiquette du contenant','Identification et dangers principaux'),('Fiche correspondant au produit','Informations détaillées de sécurité'),('Consigne du site','Organisation locale de l’alerte'),('Responsable technique','Vérification et intervention adaptée')], 'Ces supports se complètent ; une fiche d’un produit voisin ne peut pas être substituée par ressemblance de nom.'),
     choice('Quelle fiche transmettre comme document du produit ?', 'Celle dont la correspondance avec Nettoyant K est vérifiée, en indiquant toute incertitude restante.', ['La première trouvée, Nettoyant J.', 'Aucune, puisque l’étiquette est présente.'], 'Une mauvaise fiche peut orienter vers des mesures inadaptées. La correspondance doit être explicite.'),
     sequence('Traitez la découverte de l’écoulement.', ['Rester à distance et éviter une nouvelle exposition', 'Alerter avec localisation et identification disponible', 'Faire rechercher la fiche correcte et le relais technique', 'Maintenir les mesures de protection confirmées'], 'L’alerte ne doit pas attendre une lecture exhaustive de la fiche.'),
     choice('Le contenant n’a plus d’étiquette lisible. Que transmettre ?', 'Le lieu, le contenant et les signes observés, en indiquant produit non identifié.', ['Un nom supposé d’après sa couleur.', 'Une absence de danger faute de pictogramme visible.'], 'Une absence d’information augmente l’incertitude ; elle ne prouve pas l’innocuité.')])

dossier('10-07', 'Une zone ATEX et un matériel ordinaire',
    "Une atmosphère explosive peut se former dans certaines conditions avec des gaz, vapeurs, brouillards ou poussières combustibles. L’absence d’odeur ou de flamme visible ne démontre pas l’absence de danger. Les zones et équipements sont définis par l’évaluation et les règles du site.\n\nL’agent doit reconnaître la signalisation, respecter les limites d’accès et utiliser uniquement le matériel autorisé pour la situation. Il ne détermine pas seul le zonage ni la compatibilité d’un appareil. Une lampe, un téléphone ou une radio ordinaire peut ne pas être admis. En cas d’écart, la bonne réponse est le retrait vers une zone sûre et le relais compétent, sans essai d’un appareil dans la zone.",
    [('Accès à une zone de stockage', 'L’entrée porte une signalisation ATEX et renvoie à une liste de matériels autorisés. L’accès exige l’accord du responsable de zone. Le poste de l’agent se situe hors de cette zone.'),
     ('Demande du technicien', 'Un intervenant demande à emprunter la lampe personnelle de l’agent pour chercher un objet à l’intérieur. La lampe ne figure pas sur la liste. Il affirme qu’il n’y a aucune odeur.'),
     ('Consigne du site', 'Tout matériel non confirmé est maintenu hors de la zone. Les anomalies sont signalées au responsable depuis le point sûr. L’agent ne réalise ni mesure d’atmosphère ni intervention de récupération.')],
    [classify('Quels éléments autorisent une conclusion ?', ['Vérification nécessaire', 'Ne prouve pas la sécurité'], [('Compatibilité du matériel confirmée par le cadre du site',0),('Absence d’odeur',1),('Autorisation d’accès par le responsable',0),('Lampe utilisée sans incident ailleurs',1)], 'L’expérience d’un autre lieu ne valide pas un appareil dans la zone considérée.'),
     associate('Reliez les responsabilités.', [('Zonage et conditions d’intervention','Responsables compétents du site'),('Contrôle de l’accès prévu','Agent selon sa mission'),('Matériel adapté','Équipements validés pour la zone et l’usage'),('Anomalie ou doute','Alerte depuis une zone sûre')], 'La sensibilisation permet de reconnaître la limite de son rôle ; elle ne confère pas une qualification d’expert ATEX.'),
     choice('Peut-on prêter la lampe pour un essai rapide ?', 'Non, l’absence de confirmation impose de la maintenir hors de la zone.', ['Oui, pendant quelques secondes.', 'Oui, si le technicien ne sent rien.'], 'Un essai dans la zone est précisément l’exposition qu’il faut éviter.'),
     sequence('Traitez la demande.', ['Repérer la zone et les conditions d’accès', 'Constater que le matériel n’est pas confirmé', 'Refuser son introduction et saisir le responsable depuis le point sûr', 'Appliquer la solution autorisée sans improviser'], 'La demande urgente ne remplace pas la validation du matériel.'),
     choice('Le responsable fournit ensuite un matériel autorisé. L’agent peut-il entrer pour récupérer l’objet sans autre accord ?', 'Non, l’autorisation du matériel ne remplace pas les conditions d’accès et la mission de la personne.', ['Oui, le matériel autorise son porteur.', 'Oui, si le trajet est court.'], 'Matériel, accès, mission et compétence sont des conditions distinctes.')])

dossier('11-01', 'Un câble abîmé n’est pas une réparation de ronde',
    "Le risque électrique peut venir d’un contact direct avec une partie sous tension, d’un contact avec une masse devenue dangereuse ou d’un arc. La tension ne se voit pas toujours. Un appareil arrêté ou une lumière éteinte ne prouvent pas la mise en sécurité électrique.\n\nLa sensibilisation aide à reconnaître un danger et à alerter ; elle ne vaut pas habilitation pour réaliser des opérations électriques. N’ouvrez pas une armoire et ne tentez pas une réparation avec du ruban adhésif. Le périmètre et la mise hors tension relèvent des consignes et de personnes compétentes, avec les vérifications requises.",
    [('Ronde dans un local de livraison', 'Une rallonge est écrasée sous une porte métallique. Son isolant est endommagé. Le sol est humide et plusieurs salariés passent à proximité.'),
     ('Proposition d’un collègue', 'Le collègue suggère d’écarter le câble à la main puis de couvrir la partie abîmée avec du ruban. L’appareil branché ne fonctionne plus, ce qu’il considère comme une preuve d’absence de tension.'),
     ('Moyens du poste', 'L’agent peut tenir les personnes à distance sans toucher le câble et joindre le responsable technique. Il n’est pas habilité à effectuer une opération sur l’installation.')],
    [classify('Distinguez les faits et les conclusions.', ['Signe de danger à signaler', 'Ne prouve pas l’absence de tension'], [('Isolant endommagé',0),('Appareil qui ne fonctionne plus',1),('Sol humide près du câble',0),('Absence de bruit électrique',1)], 'Une installation peut rester dangereuse sans fonctionner normalement ni produire de bruit.'),
     associate('Quel rôle pour chaque action ?', [('Écarter les personnes sans contact','Protection du périmètre'),('Décrire câble et humidité','Alerte utile'),('Vérifier et sécuriser l’installation','Personnel compétent selon le cadre électrique'),('Réparer l’isolant à la main','Opération à ne pas improviser par l’agent')], 'La mise en sécurité des personnes ne nécessite pas de manipuler le câble.'),
     choice('Quelle suite est adaptée ?', 'Rester à distance, empêcher l’approche et alerter le responsable technique.', ['Déplacer le câble avec un objet improvisé.', 'Coller rapidement le ruban avant le prochain passage.'], 'Un objet courant n’est pas une protection électrique validée.'),
     sequence('Traitez le défaut repéré.', ['Identifier le danger depuis une position sûre', 'Empêcher une nouvelle exposition', 'Alerter avec localisation et signes observés', 'Attendre la confirmation de sécurisation avant la reprise prévue'], 'La disparition apparente du défaut ne suffit pas à déclarer l’installation sûre.'),
     choice('Le collègue coupe un interrupteur et affirme que tout est sûr. Que faut-il éviter ?', 'Déduire seul que toutes les conditions de sécurité électrique sont réunies.', ['Maintenir la zone protégée en attendant le personnel compétent.', 'Transmettre aux intervenants quel interrupteur a été actionné.'], 'La position d’un interrupteur ne remplace pas la procédure de mise en sécurité et les vérifications nécessaires.')])

dossier('11-02', 'Ne pas devenir la seconde victime',
    "Devant une victime possiblement en contact avec l’électricité, le premier enjeu est de ne pas établir un nouveau contact dangereux. Ne touchez pas la personne tant que le danger électrique n’est pas écarté. Alertez immédiatement et appliquez les consignes adaptées depuis une zone sûre.\n\nUne coupure peut être actionnée uniquement si elle est identifiée, accessible sans exposition et conforme aux consignes. Si les conditions ne sont pas réunies, gardez vos distances et faites intervenir les secours et le personnel compétent. Une fois la sécurité établie, les gestes de secours dépendent de votre formation et des instructions reçues. La séquence ne constitue pas une habilitation électrique ni une formation pratique aux gestes.",
    [('Atelier de maintenance', 'Une personne est immobile près d’une machine et d’un câble détérioré. L’agent ignore si elle est encore en contact électrique. Un collègue veut la tirer par le bras.'),
     ('Configuration', 'Le sol près de la victime est mouillé. Le dispositif de coupure indiqué sur la consigne est accessible depuis une zone sèche sans approcher le câble. Le PC peut joindre immédiatement les secours.'),
     ('Consigne d’urgence', 'Ne pas toucher une victime exposée à un danger électrique. Faire supprimer le danger dans les conditions prévues, alerter et empêcher l’approche. Les secours guideront la suite et les gestes adaptés après sécurisation.')],
    [classify('Quels gestes sont compatibles avec la protection initiale ?', ['Action à réaliser sans exposition', 'Danger de suraccident'], [('Empêcher le collègue de saisir la victime',0),('Tirer la victime par le bras',1),('Alerter avec mention du risque électrique et du sol mouillé',0),('Entrer dans la zone humide pour chercher la prise',1)], 'L’urgence de secours ne justifie pas de devenir une deuxième victime.'),
     associate('Reliez les données à leur importance.', [('Contact électrique possible','Interdiction d’un contact improvisé'),('Sol mouillé','Exposition aggravée à signaler'),('Coupure identifiée et accessible en sécurité','Mesure selon les consignes'),('Secours joignables','Alerte et guidage')], 'La possibilité d’une coupure dépend de la configuration réelle ; elle ne se généralise pas à tout tableau ou interrupteur.'),
     choice('Dans quel cas envisager la coupure décrite ?', 'Si le dispositif est bien identifié, accessible sans exposition et que les consignes le prévoient.', ['Dès qu’un interrupteur quelconque est visible.', 'En traversant la zone humide pour aller plus vite.'], 'La condition essentielle est de ne pas créer un nouveau contact dangereux.'),
     sequence('Organisez la réponse avec le collègue.', ['Empêcher le contact avec la victime et la zone dangereuse', 'Faire alerter immédiatement les secours', 'Faire supprimer le danger dans les conditions sûres prévues', 'Après sécurisation, suivre les instructions de secours selon ses compétences'], 'Protection et alerte peuvent être réparties et menées sans délai ; les gestes sur la victime attendent la sécurité électrique.'),
     choice('La machine cesse de faire du bruit. Peut-on toucher la victime sur ce seul indice ?', 'Non, l’arrêt du bruit ne confirme pas la suppression du danger électrique.', ['Oui, une machine silencieuse n’est plus alimentée.', 'Oui, si l’on agit très vite.'], 'Il faut une sécurisation effective, pas un signe indirect de fonctionnement.')])

dossier('12-01', 'Qualifier une alerte sans qualifier les personnes',
    "La sensibilisation à la menace sert à reconnaître des faits préoccupants, à protéger et à transmettre. L’agent n’attribue pas une intention terroriste à une apparence ou à une appartenance supposée. Une menace se décrit à partir d’éléments concrets, tout en conservant les incertitudes.\n\nUne même observation peut avoir plusieurs explications. Cela ne signifie ni banaliser un fait sérieux ni le présenter comme une certitude. La décision de sécurité s’appuie sur la situation, les consignes actualisées et les instructions des autorités. L’agent ne mène pas de recherche clandestine ni d’investigation personnelle ; il maintient son rôle de vigilance et d’alerte.",
    [('Signalement au centre culturel', 'Un visiteur signale qu’une personne photographie une porte technique. La photographie seule n’est pas interdite dans les espaces publics du centre. Le signalement ne décrit aucune menace verbale.'),
     ('Observation complémentaire', 'L’agent constate ensuite une tentative d’ouverture d’une porte portant la mention accès réservé. Il ne connaît pas la raison de ce geste ni l’autorisation de la personne.'),
     ('Circuit de traitement', 'Le PC peut vérifier les intervenants attendus. Le responsable sécurité reçoit les faits et décide des mesures prévues. L’agent peut observer à distance et traiter l’accès dans le cadre de sa mission.')],
    [classify('Quelle nature donner aux éléments ?', ['Fait à vérifier ou transmettre', 'Interprétation non établie'], [('Tentative d’ouverture d’un accès réservé',0),('Intention terroriste certaine',1),('Photographie signalée par un visiteur',0),('Danger déduit de l’apparence de la personne',1)], 'La vigilance doit rester fondée sur les faits et leur contexte, sans profilage discriminatoire.'),
     associate('Quel besoin appelle quel relais ?', [('Vérifier une intervention prévue','PC et liste des intervenants'),('Signaler le geste à la porte','Responsable sécurité'),('Apprécier une menace caractérisée','Autorités compétentes selon l’alerte'),('Maintenir le contrôle d’accès','Agent dans sa mission')], 'La chaîne de traitement évite de confondre contrôle du site et enquête sur une personne.'),
     choice('Quelle transmission est la plus utile ?', '« Une tentative d’ouverture de la porte technique a été observée ; autorisation non vérifiée à cette heure. »', ['« Terroriste repéré près d’une porte. »', '« Rien à signaler puisque la photographie est permise. »'], 'La première formulation transmet le fait pertinent sans surqualification ni banalisation.'),
     sequence('Traitez les informations successives.', ['Distinguer signalement initial et observation personnelle', 'Vérifier ce qui peut l’être sans exposition', 'Transmettre les faits et les incertitudes au PC', 'Appliquer les mesures confirmées et réévaluer'], 'Une observation nouvelle peut changer l’évaluation sans justifier une conclusion automatique sur l’intention.'),
     choice('Le PC confirme qu’il s’agit d’un technicien attendu, mais affecté à une autre porte. Que faire ?', 'Faire clarifier son accès et orienter selon la consigne, en actualisant le signalement.', ['Maintenir la qualification de menace certaine.', 'Supprimer toute règle d’accès pour ce technicien.'], 'Une explication vérifiée réduit une incertitude ; elle ne remplace pas l’autorisation de la zone concernée.')])

dossier('12-02', 'Un objet inhabituel sans manipulation',
    "Reconnaître une famille de danger ne signifie pas identifier techniquement un objet suspect. Un assemblage, un contenant ou un matériel inhabituel se décrit depuis une position sûre, sans toucher, déplacer ou ouvrir. L’agent ne cherche pas à confirmer sa nature au prix d’une exposition.\n\nL’alerte doit préciser le lieu, le contexte de découverte, ce qui est visible et les personnes potentiellement exposées. Les mesures de protection et distances relèvent des consignes du site et des autorités, sans chiffre universel improvisé. Empêchez les curieux d’approcher et évitez de diffuser des images ou des rumeurs qui compliquent la gestion.",
    [('Découverte dans un hall d’exposition', 'Un contenant inhabituel est posé près d’un accès réservé. Aucun propriétaire n’est identifié au moment du constat. Un témoin indique qu’il n’était pas présent dix minutes auparavant.'),
     ('Demande d’un exposant', 'L’exposant veut ouvrir le contenant pour vérifier s’il s’agit de matériel oublié. Il propose de le déplacer dehors afin de libérer le passage.'),
     ('Organisation d’alerte', 'L’agent peut éloigner le public du secteur sans s’approcher de l’objet et prévenir le PC depuis un point sûr. Le responsable applique la procédure prévue et sollicite les autorités compétentes.')],
    [classify('Quels actes sont adaptés ?', ['Protection et transmission', 'Manipulation à écarter'], [('Décrire l’emplacement depuis un point sûr',0),('Ouvrir pour identifier le contenu',1),('Empêcher les curieux d’approcher',0),('Transporter l’objet à l’extérieur',1)], 'La recherche d’une certitude ne justifie pas une manipulation. Le déplacement peut aussi transférer le danger vers d’autres personnes.'),
     associate('Reliez les informations à leur statut.', [('Position observée par l’agent','Constat direct'),('Absence dix minutes plus tôt selon le témoin','Déclaration attribuée'),('Nature exacte du contenu','Inconnue'),('Procédure du site et instructions des autorités','Cadre des mesures de protection')], 'La nature inconnue doit rester indiquée ; ne pas savoir n’est pas une raison d’ouvrir.'),
     choice('Quelle réponse donner à l’exposant ?', '« Ne le manipulez pas ; nous protégeons le secteur et alertons selon la procédure. »', ['« Ouvrez-le doucement pour limiter le risque. »', '« Portez-le loin du public, puis nous appellerons. »'], 'Les premières mesures évitent l’exposition et préservent l’évaluation par les intervenants compétents.'),
     sequence('Organisez la prise en compte.', ['Cesser l’approche et observer depuis une position sûre', 'Protéger les personnes du secteur sans manipulation', 'Alerter avec localisation, contexte et incertitudes', 'Appliquer les instructions et empêcher les retours non autorisés'], 'Les actions de protection et d’alerte se coordonnent sans attendre une identification technique.'),
     choice('Un passant affirme que le contenant lui appartient. Peut-on immédiatement le laisser l’ouvrir ?', 'Il faut transmettre l’information et suivre la vérification prévue avant de modifier les mesures.', ['Oui, toute revendication de propriété clôt l’alerte.', 'Non, il faut le déclarer coupable.'], 'L’affirmation est un élément nouveau à vérifier, pas une preuve automatique dans un sens ou dans l’autre.')])

dossier('12-03', 'Traduire une consigne Vigipirate en actions de poste',
    "Le dispositif national et ses consignes évoluent. Au poste, l’agent doit utiliser les instructions actualisées reçues pour son site, connaître les mesures qui le concernent et savoir à qui signaler une difficulté. Une affiche ancienne ou une information trouvée isolément ne remplace pas la consigne validée.\n\nLa vigilance s’intègre au fonctionnement : accès, livraisons, zones sensibles, signalements et accueil du public. Une mesure doit être comprise dans sa finalité et dans ses limites. Renforcer le contrôle ne signifie pas créer des pouvoirs supplémentaires ni bloquer une issue nécessaire. Les incompatibilités pratiques se font remonter pour arbitrage.",
    [('Instruction actualisée du site', 'Toutes les livraisons sont annoncées au PC ; les véhicules non prévus attendent dans la zone dédiée. Le cheminement secours doit rester libre. La consigne est datée et validée par la direction sécurité.'),
     ('Affiche conservée au poste', 'Une ancienne affiche indique de fermer systématiquement le portail de service pendant toute livraison. Elle n’a pas été retirée après la réorganisation des accès.'),
     ('Situation du matin', 'Un véhicule non annoncé arrive au moment où une livraison autorisée occupe le quai. Le responsable confirme que la zone d’attente reste disponible et que l’accès secours ne doit pas être encombré.')],
    [classify('Quelles mesures sont prévues dans le dossier actuel ?', ['Mesure confirmée', 'Mesure non justifiée par cette seule situation'], [('Vérifier la livraison auprès du PC',0),('Faire attendre dans la zone dédiée',0),('Bloquer le cheminement secours avec le véhicule',1),('Imposer une fouille non prévue au seul motif du renforcement',1)], 'Le renforcement de vigilance s’applique dans le cadre légal et ne doit pas créer un autre danger.'),
     associate('Reliez les contrôles documentaires.', [('Date de la consigne','Actualité'),('Validation direction sécurité','Autorité interne compétente'),('Zone d’attente et accès secours','Application concrète au poste'),('Ancienne affiche','Document à faire retirer ou corriger')], 'Une consigne doit être retrouvable, compréhensible et cohérente avec l’organisation réelle.'),
     choice('Que faire du véhicule non annoncé ?', 'Le maintenir dans la zone d’attente prévue et demander la vérification au PC.', ['Le placer devant l’accès secours pour l’avoir en vue.', 'Le laisser entrer puisqu’une autre livraison est déjà autorisée.'], 'L’autorisation d’une livraison ne couvre pas un autre véhicule ; l’attente doit rester sûre.'),
     sequence('Préparez votre prise de poste.', ['Lire la consigne actualisée et son périmètre', 'Vérifier les moyens et les zones correspondantes', 'Faire clarifier les contradictions avant application', 'Transmettre les points sensibles à la relève'], 'La préparation réduit les décisions improvisées au moment où le flux augmente.'),
     choice('Une nouvelle instruction officielle est relayée par la direction en cours de vacation. Quelle suite ?', 'Vérifier sa portée pour le poste et appliquer la mise à jour confirmée.', ['Conserver l’ancienne parce qu’elle a été lue le matin.', 'Inventer une mesure plus sévère pour être certain.'], 'L’actualisation est une tâche continue ; la sévérité seule n’est pas un critère de pertinence.')])

dossier('12-04', 'Un faisceau de faits, pas un portrait supposé',
    "L’observation professionnelle décrit des comportements, leur répétition, leur contexte et les écarts à une règle connue. Elle ne confond pas apparence et menace. Des gestes ordinaires peuvent devenir pertinents par leur combinaison ou leur évolution, mais leur signification reste à vérifier.\n\nUn signalement exploitable permet au destinataire de refaire le raisonnement : quoi, où, quand, source, répétition éventuelle et mesure déjà prise. La description d’une personne, lorsqu’elle est nécessaire, reste factuelle et proportionnée. L’agent ne diffuse pas de portrait accusatoire sur un groupe privé ni ne poursuit une personne hors de son cadre.",
    [('Trois observations dans un centre de congrès', 'Une personne consulte son téléphone près d’une sortie. Une autre cherche plusieurs fois à entrer dans une zone réservée malgré des orientations vers l’accueil. Une troisième photographie une œuvre exposée au public.'),
     ('Signalement d’un visiteur', 'Le visiteur désigne la personne au téléphone comme dangereuse en raison de son apparence. Il ne décrit aucun geste menaçant ni tentative d’accès interdit de sa part.'),
     ('Consigne du poste', 'Les tentatives répétées d’accès réservé sont signalées au PC avec heure et lieu. Le PC vérifie les accréditations. Les photographies d’œuvres sont autorisées dans cette salle.')],
    [classify('Quels faits justifient ici une vérification spécifique au PC ?', ['Écart concret à vérifier', 'Ne constitue pas à lui seul cet écart'], [('Tentatives répétées d’entrée en zone réservée',0),('Utilisation d’un téléphone',1),('Apparence jugée inquiétante par un visiteur',1),('Photographie autorisée d’une œuvre',1)], 'La sélection du signalement repose sur la règle et le comportement, pas sur un profil supposé.'),
     associate('Reliez les éléments du bon signalement.', [('Heures des tentatives','Répétition observable'),('Porte de zone réservée','Localisation et règle'),('Orientations déjà données','Actions réalisées'),('Accréditation inconnue','Vérification attendue du PC')], 'Ces détails permettent une vérification ciblée sans accusation générale.'),
     choice('Quelle phrase transmettre ?', '« Trois tentatives d’accès à la zone réservée ont été observées après orientation vers l’accueil ; accréditation à vérifier. »', ['« Une personne au profil dangereux téléphone près d’une sortie. »', '« Tout photographe est suspect. »'], 'La formulation précise le comportement et la vérification demandée.'),
     sequence('Traitez le signalement du visiteur.', ['Écouter ce qu’il a réellement observé', 'Séparer faits et jugement d’apparence', 'Recouper avec vos observations et la consigne', 'Transmettre les éléments pertinents sans reprendre le jugement'], 'Un signalement reçu n’est pas une vérité à recopier ; sa source et son contenu doivent être examinés.'),
     choice('Le PC confirme une accréditation, mais pour une autre zone. Que faire ?', 'Orienter la personne vers la zone autorisée et maintenir la limite de l’autre accès.', ['Laisser accéder partout.', 'Maintenir une accusation de menace sans autre fait.'], 'L’accréditation précise un droit d’accès ; elle ne se réduit pas à un statut oui ou non pour tout le site.')])

dossier('12-05', 'Un appel menaçant à transmettre fidèlement',
    "Un appel menaçant doit être traité sérieusement sans en garantir soi-même l’authenticité. Les mots exacts utiles, l’heure, le numéro affiché s’il existe et les éléments entendus doivent être distingués des interprétations. Un bruit ne permet pas d’affirmer une localisation ou une identité.\n\nSi la situation le permet, restez calme et recueillez les précisions prévues par la procédure, sans provocation ni promesse. Alertez le circuit compétent dès que possible et conservez les traces selon les règles du site. Les décisions de protection ne doivent pas être improvisées au seul niveau de l’agent recevant l’appel.",
    [('Note prise pendant l’appel', 'À 16 h 08, une voix déclare : « Vous devez faire sortir les gens du bâtiment B. » L’interlocuteur raccroche avant toute précision sur le motif. Aucun numéro n’est affiché.'),
     ('Ce qui a été entendu', 'Un bruit de circulation est audible. L’agent n’a pas reconnu la voix et ne sait pas d’où vient l’appel. Il a noté les mots avant de prévenir le PC.'),
     ('Procédure du site', 'Transmettre immédiatement au PC et au responsable par le circuit prévu, avec les termes de l’appel et les incertitudes. Préserver les traces disponibles sans les partager sur une messagerie personnelle.')],
    [classify('Distinguez données et suppositions.', ['Élément à transmettre comme tel', 'Supposition à ne pas affirmer'], [('Heure 16 h 08',0),('Appel nécessairement passé depuis la rue du site',1),('Absence de numéro affiché',0),('Identité reconnue de l’appelant',1)], 'Le bruit de circulation et une impression de voix ne permettent pas une localisation ou une identification certaine.'),
     associate('Associez les éléments de la fiche.', [('Mots visant le bâtiment B','Contenu de l’appel'),('16 h 08','Heure de réception'),('Numéro non affiché','Information technique disponible'),('Voix non reconnue','Limite d’identification')], 'Une case inconnue doit rester inconnue ; elle ne se remplit pas par déduction.'),
     choice('Quelle transmission conserve la fidélité ?', 'Rapporter les mots notés, l’heure et le raccrochage, en précisant que le motif et la localisation sont inconnus.', ['Annoncer qu’un engin a été confirmé dans B.', 'Présenter l’appel comme une plaisanterie faute de numéro.'], 'Le contenu doit être pris en compte sans ajout ni minimisation.'),
     sequence('Après le raccrochage, organisez la suite.', ['Fixer les mots et données encore en mémoire sans les compléter', 'Alerter immédiatement le circuit compétent', 'Préserver les traces selon la procédure', 'Appliquer les mesures décidées et transmettre toute nouvelle information'], 'La rédaction ne doit pas retarder l’alerte ; une note brève peut être complétée avec sa source et son heure.'),
     choice('Un second appel donne une autre information. Comment l’enregistrer ?', 'Comme un nouvel événement avec son heure et ses termes, relié au premier sans le remplacer.', ['Modifier la première note pour produire une version unique.', 'Ignorer le second parce que le premier a été transmis.'], 'Conserver la succession des informations aide les décideurs à évaluer l’évolution.')])

dossier('12-06', 'Une alerte physique et une anomalie informatique',
    "Les menaces non conventionnelles et numériques ne se traitent pas par une investigation improvisée. Une substance inconnue, plusieurs personnes présentant des symptômes ou un comportement inhabituel d’un système se signalent avec des faits précis. L’agent protège, alerte et évite de propager le danger ou l’incident.\n\nUn message informatique alarmant peut relever d’une fraude, d’une panne ou d’un incident de sécurité. Ne cliquez pas sur une pièce jointe et ne branchez pas un support inconnu pour comprendre. Préservez les éléments visibles et utilisez le relais informatique prévu. Les mesures de confinement, de secours ou de continuité dépendent des instructions compétentes et du contexte réel.",
    [('Poste de réception', 'Une enveloppe ouverte présente une substance inconnue sur le bureau. Deux personnes à proximité signalent une irritation. L’origine de la substance n’est pas connue.'),
     ('Message reçu au même moment', 'Un courriel prétend expliquer l’incident et demande d’ouvrir une pièce jointe sur le poste de contrôle. L’expéditeur n’est pas vérifié. Le responsable informatique est joignable par un numéro connu.'),
     ('Consignes', 'Ne pas manipuler la substance, limiter l’exposition et alerter les secours et le responsable selon la procédure. Ne pas ouvrir le fichier ; transmettre les éléments du message au service informatique par le canal prévu.')],
    [classify('Associez les mesures au bon domaine.', ['Protection face à la substance', 'Protection du système informatique', 'À écarter'], [('Éviter de disperser ou toucher la substance',0),('Ne pas ouvrir la pièce jointe',1),('Souffler sur la poudre pour dégager le bureau',2),('Joindre l’informatique via un contact connu',1)], 'Les deux incidents peuvent être liés ou non. Il faut protéger les personnes et le système sans inventer de lien certain.'),
     associate('Que transmettre à qui ?', [('Irritations et substance inconnue','Secours et responsable de site'),('Courriel suspect et pièce jointe non ouverte','Service informatique'),('Personnes potentiellement exposées','Circuit de secours prévu'),('État du poste de contrôle','Responsable de continuité')], 'Les informations utiles varient selon le destinataire ; la diffusion générale du message n’est pas nécessaire.'),
     choice('Le courriel affirme être officiel. Que vérifier ?', 'Son authenticité par le circuit connu, sans utiliser les liens ou contacts qu’il fournit comme seule preuve.', ['Seulement son logo.', 'Son contenu en ouvrant la pièce jointe.'], 'Le message ne peut pas s’authentifier lui-même.'),
     sequence('Coordonnez les premières actions.', ['Éviter une nouvelle exposition physique et numérique', 'Alerter les relais compétents avec les faits', 'Préserver les éléments sans manipulation ou ouverture', 'Appliquer les instructions et organiser la continuité autorisée'], 'Les actions peuvent être réparties ; aucune recherche de cause ne doit retarder la protection.'),
     choice('Peut-on annoncer immédiatement une attaque NRBC et cyber coordonnée ?', 'Non, on signale les deux anomalies et les incertitudes sans affirmer leur nature ou leur lien.', ['Oui, leur simultanéité le prouve.', 'Non, donc il ne faut rien signaler.'], 'La simultanéité est un fait pertinent, pas une preuve causale ; l’alerte reste nécessaire.')])

dossier('12-07', 'Protéger, alerter et orienter les secours après une attaque',
    "Après des détonations ou une explosion, la protection dépend du danger encore présent, des possibilités de s’échapper ou de se mettre à l’abri et des instructions des forces de l’ordre. Ne retournez pas dans une zone dangereuse pour filmer ou chercher des objets. Une information sur les victimes doit rester liée à ce qui est observable depuis un endroit sûr.\n\nUne blessure apparente peut sous-estimer la gravité. Le nombre de personnes, leur localisation et les signes visibles aident les secours sans établir un diagnostic. Les gestes de secours s’effectuent lorsque les conditions le permettent, selon la formation reçue et les instructions. La formation pratique correspondante reste indispensable ; le rôle de cette séquence est de comprendre les priorités et le relais.",
    [('Situation dans un centre commercial', 'Des détonations sont entendues dans une aile. Depuis une zone protégée, l’agent voit deux personnes au sol près d’une sortie. Il ne sait pas si la menace est terminée.'),
     ('Accès et public', 'Une issue éloignée de l’aile concernée est accessible aux personnes présentes près de l’agent. D’autres veulent retourner chercher un sac ou filmer. Les accès doivent rester disponibles pour les intervenants.'),
     ('Alerte', 'Le PC et les secours peuvent être joints depuis le point sûr. L’agent connaît le nom de l’aile et l’accès extérieur correspondant. Il ne connaît pas le nombre total de victimes ni l’auteur des détonations.')],
    [classify('Distinguez information certaine et limite.', ['Observation ou information disponible', 'Non établi'], [('Deux personnes visibles au sol',0),('Menace définitivement terminée',1),('Accès extérieur identifié',0),('Nombre total de victimes du site',1)], 'Un décompte partiel doit être présenté comme tel, sans sous-estimer ni inventer d’autres victimes.'),
     associate('Reliez les priorités.', [('Menace possiblement active','Protéger et éviter le retour en zone exposée'),('Personnes près d’une issue sûre','Orienter selon la situation et les consignes'),('Victimes visibles','Transmettre localisation et signes observables'),('Forces de l’ordre arrivant','Suivre leurs instructions et éviter tout geste ambigu')], 'Les secours et la protection se coordonnent ; l’agent ne doit pas exposer un groupe pour rejoindre une victime.'),
     choice('Que dire à une personne voulant retourner chercher un sac ?', 'Lui demander de rester en sécurité et de ne pas retourner dans la zone dangereuse.', ['L’accompagner pour réduire le temps de retour.', 'L’autoriser si elle promet de courir.'], 'Un objet personnel ne justifie pas une nouvelle exposition.'),
     sequence('Structurez votre alerte depuis l’abri.', ['Indiquer lieu et nature des faits entendus ou vus', 'Préciser que la menace actuelle est inconnue', 'Donner les victimes visibles et l’accès utilisable', 'Écouter les instructions et transmettre l’évolution'], 'L’alerte reste précise sur ses limites ; elle ne retarde pas la mise en sécurité.'),
     choice('Une personne à proximité est blessée dans la zone désormais confirmée sûre. Quelle suite ?', 'Appliquer les gestes pour lesquels on est formé et suivre les instructions des secours.', ['Improviser une technique apprise seulement dans un texte.', 'Attendre sans alerter parce que la blessure paraît petite.'], 'La sécurité établie permet la prise en charge adaptée, sans dépasser ses compétences.')])

dossier('13-01', 'Corriger une main courante sans effacer l’histoire',
    "La main courante numérique assure une continuité d’information et une traçabilité. L’identité de l’auteur, l’heure des faits, l’heure de saisie et les corrections doivent rester compréhensibles. Utiliser le compte d’un collègue ou réécrire discrètement une entrée affaiblit cette traçabilité.\n\nUne erreur se corrige par la fonction ou la procédure prévue, en conservant la relation entre l’entrée initiale et le complément. Le contenu reste factuel et proportionné : pas de diagnostic, d’accusation ou de donnée personnelle inutile. La recherche d’une présentation propre ne justifie pas l’effacement d’un événement réel.",
    [('Entrée du journal', 'À 09 h 20, l’agent saisit : « Porte atelier A ouverte à 09 h 05, PC prévenu à 09 h 07. » Il constate ensuite qu’il s’agissait de l’atelier B. Les heures sont correctes.'),
     ('Fonctions de l’outil', 'Le logiciel permet d’ajouter un complément daté et lié à l’entrée. Chaque agent possède un compte individuel. Les droits de suppression sont réservés à une procédure d’administration.'),
     ('Demande d’un collègue', 'Le collègue propose d’utiliser son compte administrateur pour remplacer A par B sans laisser de trace. L’agent de relève a déjà lu l’entrée initiale.')],
    [classify('Quelles pratiques préservent la traçabilité ?', ['Pratique adaptée', 'Pratique à écarter'], [('Complément daté corrigeant A en B',0),('Utilisation du compte du collègue',1),('Information de la relève sur la correction',0),('Suppression discrète de l’entrée initiale',1)], 'La correction doit être visible pour les personnes qui ont déjà utilisé la première information.'),
     associate('Reliez les champs à leur sens.', [('09 h 05','Heure du fait'),('09 h 07','Heure de l’alerte'),('09 h 20','Heure de saisie'),('Complément ultérieur','Correction traçable du lieu')], 'Les horodatages décrivent des étapes différentes et ne doivent pas être confondus.'),
     choice('Quel complément est le plus précis ?', '« Correction de l’entrée : le lieu est l’atelier B, et non A ; les heures restent inchangées. »', ['« Tout était faux, ignorer l’incident. »', '« Atelier B », sans lien avec l’entrée.'], 'La correction délimite exactement ce qui change et ce qui reste valable.'),
     sequence('Corrigez l’erreur.', ['Vérifier le lieu exact à partir des éléments disponibles', 'Ajouter le complément lié avec son propre compte', 'Informer les destinataires ayant utilisé l’entrée', 'Vérifier que le suivi porte désormais sur le bon lieu'], 'La correction documentaire et la correction opérationnelle doivent aller ensemble.'),
     choice('Le responsable demande l’historique. Que fournir ?', 'L’entrée et ses compléments par le canal autorisé, avec leurs auteurs et dates disponibles.', ['Seulement une version réécrite sans les corrections.', 'Une capture personnelle envoyée à tous.'], 'L’historique utile reste dans le circuit professionnel et conserve les liens entre événements.')])

dossier('13-02', 'Continuer le suivi pendant une panne',
    "Une panne de l’outil ne supprime pas le besoin de tracer et de transmettre. Le mode dégradé doit être prévu : support de secours, auteur, heures, confidentialité, conservation et reprise dans l’outil. L’agent ne crée pas un fichier personnel non protégé pour remplacer durablement le système.\n\nLors de la reprise, distinguez les heures réelles des événements et l’heure de retranscription. Évitez les doublons en reliant l’entrée reprise à la référence du support temporaire. Ne détruisez pas ce support hors de la procédure de conservation. Un incident encore actif doit être transmis oralement sans attendre le retour du logiciel.",
    [('Panne à 22 h', 'La main courante ne répond plus. Le support papier de secours numéroté est disponible au poste. Il est conservé dans un rangement sécurisé accessible aux agents autorisés.'),
     ('Événements pendant la panne', 'À 22 h 12, un défaut de portail est signalé au PC. À 22 h 18, un contrôle manuel est mis en place. Le défaut reste actif à la relève de 23 h.'),
     ('Retour du système à 23 h 20', 'L’outil fonctionne de nouveau. La procédure prévoit la reprise avec mention du mode dégradé, des heures des faits et de la référence du feuillet, puis conservation du support selon les règles.')],
    [classify('Quels choix conviennent au mode dégradé ?', ['Conforme au dispositif décrit', 'À écarter'], [('Utiliser le support numéroté prévu',0),('Attendre le retour du logiciel avant d’alerter sur le portail',1),('Conserver le support dans le rangement sécurisé',0),('Noter les identités dans une messagerie personnelle',1)], 'Le mode dégradé assure simultanément continuité, confidentialité et traçabilité.'),
     associate('Reliez les heures.', [('22 h','Début de panne'),('22 h 12','Signalement du défaut'),('22 h 18','Mise en place du contrôle manuel'),('23 h 20','Retour du système et reprise possible')], 'La reprise ne doit pas déplacer tous les événements à 23 h 20.'),
     choice('Comment reprendre le défaut dans l’outil ?', 'Avec son heure réelle, la mention de reprise après panne et la référence du support de secours.', ['Comme un nouveau défaut survenu à 23 h 20.', 'En supprimant les détails du contrôle manuel.'], 'La reprise conserve l’histoire de l’événement et permet d’éviter les doublons.'),
     sequence('Organisez la continuité.', ['Déclencher le support de secours et signaler la panne', 'Tracer les événements et transmettre les urgences', 'Faire une relève explicite des points ouverts', 'Reprendre dans l’outil et conserver le support selon la procédure'], 'La relève ne doit pas attendre la réparation informatique pour connaître le défaut actif.'),
     choice('Une entrée a déjà été reprise par la relève. Que faire avant une seconde saisie ?', 'Vérifier la référence et compléter si nécessaire sans créer un doublon.', ['Saisir une deuxième fois pour être certain.', 'Effacer le feuillet sans contrôle.'], 'La référence commune permet de relier les supports et de préserver un seul suivi opérationnel.')])

dossier('14-01', 'Une dégradation vue depuis le poste',
    "Face à une possible infraction, la première analyse porte sur les faits, les personnes exposées, les limites de perception et les possibilités de relais. Une qualification juridique ne remplace pas cette analyse. La protection des personnes peut être prioritaire par rapport à la conservation d’un bien.\n\nL’agent ne poursuit pas une logique de sanction. Il observe, alerte et agit dans les conditions de son cadre d’intervention. L’article 73, la légitime défense et l’assistance répondent à des conditions distinctes ; on ne choisit pas l’un comme formule générale pour toute action. Le compte rendu doit permettre de comprendre pourquoi une mesure a été prise et quand elle a été adaptée.",
    [('Observation dans une galerie', 'Depuis le poste, l’agent voit une personne frapper une vitrine avec un objet. Des éclats tombent près de visiteurs. Il n’a pas entendu les échanges qui ont précédé.'),
     ('Configuration', 'Le PC peut alerter les forces de l’ordre. Une issue latérale permet d’écarter les visiteurs sans passer près de la vitrine. Un collègue peut aider à protéger le passage.'),
     ('Évolution', 'La personne pose l’objet puis s’éloigne. Des débris restent au sol. Le commerçant demande à l’agent de la poursuivre seul et de récupérer de force une indemnisation.')],
    [classify('Quels éléments sont établis ?', ['Observation personnelle', 'Non établi ou hors finalité'], [('Coups sur la vitrine',0),('Cause de la dispute précédente',1),('Éclats près des visiteurs',0),('Droit de récupérer de force une indemnisation',1)], 'Le dommage constaté n’autorise pas un recouvrement privé forcé.'),
     associate('Reliez les besoins aux réponses.', [('Visiteurs près des éclats','Mise à distance et cheminement sûr'),('Dégradation observée','Alerte factuelle aux autorités'),('Objet posé et départ','Réévaluation du danger actuel'),('Débris au sol','Protection du périmètre et relais technique')], 'La fin du geste violent ne supprime pas les dangers matériels laissés sur place.'),
     choice('Quelle priorité ressort de la configuration ?', 'Protéger les visiteurs et alerter en décrivant les faits.', ['Poursuivre seul pour obtenir le paiement.', 'Réunir d’abord tous les témoignages avant d’alerter.'], 'La collecte d’informations ne doit pas retarder une protection ou une alerte urgente.'),
     sequence('Présentez votre décision.', ['Décrire le geste et les personnes exposées', 'Expliquer les mesures de protection et l’alerte', 'Indiquer l’arrêt du geste et le départ observé', 'Transmettre les risques résiduels et le relais'], 'La décision est reliée aux faits successifs et à la finalité de sécurité.'),
     choice('Le commerçant exige de ramasser l’objet pour le photographier. Quelle réponse ?', 'Éviter une manipulation inutile, protéger les lieux et demander les instructions des autorités.', ['Le déplacer pour obtenir une meilleure photo.', 'Le remettre à un témoin pour qu’il le conserve.'], 'La préservation des traces doit rester compatible avec la sécurité et le relais aux enquêteurs.')])

dossier('14-02', 'Comparer alarme, images et ticket',
    "Une décision solide croise les sources sans donner à chacune plus de portée qu’elle n’en a. Une alarme signale un événement, une image montre un angle et une période, un ticket renseigne une transaction. Une rupture d’observation ou une mauvaise qualité d’image doit rester explicitement mentionnée.\n\nLa vérification volontaire peut résoudre un doute, mais son refus ne remplit pas les éléments manquants d’une infraction. L’agent doit savoir conclure que les faits ne suffisent pas, tout en transmettant ce qui reste utile. La pression commerciale ne transforme pas l’incertitude en preuve.",
    [('Portique d’un magasin de sport', 'Le portique sonne lors du départ d’une cliente. Elle présente un ticket indiquant deux articles. Une veste porte encore un dispositif antivol.'),
     ('Images consultées par une personne habilitée', 'Les images montrent la cliente prenant une veste puis un passage en caisse. L’écran ne permet pas de lire les étiquettes des articles payés. Aucun suivi continu ne montre une dissimulation.'),
     ('Vérification de caisse', 'La caissière peut comparer le ticket et les références avec l’accord de la cliente. Le responsable souhaite éviter une accusation prématurée. La cliente reste calme.')],
    [classify('Quelle portée donner aux éléments ?', ['Élément constaté', 'Conclusion non démontrée'], [('Dispositif antivol encore présent',0),('Vol prouvé par le seul signal',1),('Passage en caisse visible',0),('Correspondance certaine des références grâce aux images floues',1)], 'Un élément peut soutenir une vérification sans suffire à établir l’ensemble des faits.'),
     associate('Associez source et limite.', [('Portique','Ne démontre pas seul l’absence de paiement'),('Images','Ne lisent pas les références payées'),('Ticket','Doit être rapproché des articles concernés'),('Caissière','Peut vérifier la transaction dans son cadre')], 'La comparaison des sources évite de demander à une image ou à une alarme ce qu’elle ne peut prouver.'),
     choice('Quelle prochaine action est proportionnée ?', 'Proposer une comparaison du ticket et des références avec la caissière.', ['Imposer une reconnaissance de vol avant vérification.', 'Retenir automatiquement la cliente parce que la veste sonne.'], 'Les éléments disponibles appellent une clarification, pas une conclusion automatique.'),
     sequence('Organisez la vérification.', ['Expliquer le signal et la difficulté précise', 'Proposer la vérification consentie avec la caisse', 'Comparer les références et noter le résultat utile', 'Adapter la suite aux faits confirmés'], 'La conclusion vient après la comparaison et reste limitée à ce qu’elle établit.'),
     choice('Le paiement est confirmé et le dispositif avait été oublié. Quelle trace conserver ?', 'Un récit factuel de l’alarme, de la vérification et de sa résolution, selon la procédure.', ['Une mention de vol suspecté maintenue sans le résultat.', 'Une accusation contre la cliente pour avoir fait sonner.'], 'Le résultat favorable doit apparaître clairement ; l’événement technique ne doit pas devenir une accusation durable.')])

dossier('14-03', 'Une alarme incendie pendant un litige d’accès',
    "Une alarme incendie modifie les priorités. L’agent applique les consignes du site, alerte et contribue à la mise en sécurité selon son rôle. La mission APS ne se confond pas automatiquement avec celle d’un personnel qualifié en sécurité incendie ; les responsabilités et limites doivent être connues.\n\nNe bloquez pas les cheminements d’évacuation pour poursuivre un contrôle d’accès ordinaire. La levée de doute, l’usage des équipements et la réintégration dépendent de l’organisation et des compétences prévues. Une absence de fumée visible au poste ne prouve pas que tout le bâtiment est sûr.",
    [('Accueil d’un immeuble tertiaire', 'Un visiteur attend la confirmation de son rendez-vous. Une alarme incendie se déclenche. L’agent est chargé d’appliquer les consignes d’évacuation de l’accueil et d’informer le PC.'),
     ('Organisation incendie', 'Le site dispose d’un responsable et d’une équipe désignée. Le point de rassemblement est indiqué. Les agents d’accueil ne réarment pas seuls le système et n’autorisent pas la réintégration.'),
     ('Demandes contradictoires', 'Un salarié demande de continuer à contrôler les badges à la sortie. Un autre veut rentrer chercher son ordinateur. Aucune autorisation de réintégration n’a été donnée.')],
    [classify('Quelles actions conviennent au rôle décrit ?', ['Action prévue', 'Action à ne pas improviser'], [('Informer le PC et appliquer les consignes d’évacuation',0),('Bloquer la sortie pour contrôler chaque badge',1),('Orienter vers le rassemblement prévu',0),('Réarmer seul le système pour faire cesser le bruit',1)], 'L’alarme impose la priorité de mise en sécurité et le respect du rôle attribué.'),
     associate('Reliez les décisions aux interlocuteurs.', [('Application des consignes d’accueil','Agent du poste'),('Gestion technique du système','Personnel compétent prévu'),('Réintégration','Autorité désignée par l’organisation de sécurité'),('Information sur personnes ou zones concernées','Transmission au PC et aux intervenants')], 'Le rôle de l’agent est utile sans absorber toutes les fonctions incendie.'),
     choice('Que dire au salarié qui veut son ordinateur ?', 'Ne pas retourner dans le bâtiment avant l’autorisation prévue.', ['Entrer rapidement s’il ne voit pas de fumée.', 'L’accompagner pour rendre le retour sûr.'], 'L’absence de fumée à l’accueil ne confirme pas la sécurité de l’ensemble des locaux.'),
     sequence('Organisez la réponse au poste.', ['Prendre en compte l’alarme et alerter selon la consigne', 'Maintenir les cheminements de mise en sécurité', 'Transmettre les informations utiles au PC', 'Attendre les instructions de fin d’alerte et de réintégration'], 'Le contrôle d’accès reprend dans des conditions confirmées, pas sur la seule fin du signal sonore.'),
     choice('La sirène s’arrête. La réintégration est-elle automatiquement autorisée ?', 'Non, il faut la confirmation prévue par l’organisation du site.', ['Oui, le silence suffit.', 'Oui, si les salariés le demandent.'], 'Arrêt de signal et décision de réintégration sont deux faits distincts.')])

dossier('14-04', 'La décision doit suivre l’évolution',
    "Une intervention n’est pas un scénario figé. À chaque changement, réexaminez la menace, les personnes exposées, les moyens et le besoin de relais. Une mesure justifiée au départ peut devenir inutile ou excessive ensuite ; une situation calme peut aussi s’aggraver.\n\nDécrire les points de bascule aide à comprendre l’action : apparition d’un objet, arrivée de tiers, arrêt de la menace, malaise ou changement de lieu. L’agent ne conserve pas une stratégie pour rester cohérent avec sa première impression. Sa cohérence consiste à relier chaque choix à l’état réel de la situation.",
    [('Début d’incident', 'Deux personnes se disputent près de l’entrée d’un entrepôt. L’une crie, l’autre recule. L’agent demande un renfort et maintient les tiers à distance.'),
     ('Évolution', 'Les deux personnes cessent de se menacer. L’une s’assoit brusquement et dit manquer d’air. Le collègue arrive et pense encore intervenir pour une bagarre en cours.'),
     ('Moyens', 'Le PC peut joindre les secours. Une zone dégagée permet une prise en charge sans circulation d’engins. Aucun diagnostic n’a été établi et la personne répond aux questions simples.')],
    [classify('Quel état correspond au moment actuel ?', ['Fait actuel', 'Information initiale à actualiser'], [('Personne assise déclarant manquer d’air',0),('Bagarre toujours en cours',1),('Menaces verbales initiales',1),('Renfort maintenant présent',0)], 'L’information initiale explique le déclenchement, mais ne décrit pas nécessairement l’état à l’arrivée du renfort.'),
     associate('Reliez le changement à l’adaptation.', [('Menaces cessées','Réduire la logique de confrontation'),('Difficulté respiratoire déclarée','Demander l’aide de secours adaptée'),('Renfort arrivé','Lui transmettre l’état actuel'),('Circulation d’engins proche','Préserver un espace sûr')], 'La sécurité et le secours peuvent devenir la priorité alors que le signalement initial concernait un conflit.'),
     choice('Quelle première information donner au collègue ?', '« Les menaces ont cessé ; cette personne signale une difficulté respiratoire, j’alerte les secours. »', ['« Maîtrisez-les, on m’a appelé pour une bagarre. »', '« Tout est fini, repartez. »'], 'La mise à jour évite une intervention fondée sur une situation qui a changé.'),
     sequence('Réévaluez l’intervention.', ['Observer le changement et les dangers résiduels', 'Actualiser le PC et le renfort', 'Mettre en œuvre le secours et la protection adaptés', 'Tracer les différentes phases et les relais'], 'La chronologie rend compréhensible le changement de stratégie.'),
     choice('La personne se relève et veut partir. Quelle attitude adopter ?', 'Transmettre l’évolution aux secours et suivre leurs instructions, sans inventer un diagnostic ni un pouvoir de contrainte.', ['Déclarer le malaise simulé.', 'La retenir pour la punir du conflit initial.'], 'Le comportement nouveau ne permet pas une conclusion médicale ou une sanction privée.')])

dossier('14-05', 'Préserver une trace sans la transformer',
    "Préserver des traces consiste d’abord à éviter leur altération et à limiter les accès inutiles, sous réserve de la protection urgente des personnes. L’agent ne mène pas les opérations de police technique : il ne prélève pas, ne teste pas et ne reconstitue pas les lieux pour obtenir une meilleure présentation.\n\nLorsque la sécurité impose un déplacement, il faut transmettre ce qui a été déplacé, par qui, quand et pourquoi. Une trace matérielle, une image et un témoignage ne se conservent pas de la même manière ; les personnes habilitées et les circuits de remise doivent être identifiés. La curiosité ou la volonté d’aider ne justifient pas une manipulation.",
    [('Découverte d’une porte forcée', 'À la ronde, l’agent voit une porte endommagée et un outil posé au sol. Personne n’est visible à l’intérieur. Des employés arrivent pour prendre leur poste.'),
     ('Risque matériel', 'Des débris coupants occupent le passage habituel. Un autre chemin permet d’écarter les employés sans déplacer l’outil. Le PC a appelé les forces de l’ordre.'),
     ('Demandes', 'Le responsable veut ranger l’outil dans son bureau. Un collègue veut nettoyer les débris avant l’arrivée de la police. Le circuit de vidéoprotection est géré par des personnes habilitées.')],
    [classify('Quelles actions préservent les éléments ?', ['Action adaptée au cas', 'Altération inutile à éviter'], [('Orienter les employés vers l’autre chemin',0),('Ranger l’outil pour dégager la vue',1),('Limiter les accès à la zone',0),('Nettoyer avant les instructions sans nécessité de secours',1)], 'Le chemin alternatif permet de protéger les personnes sans modifier les lieux.'),
     associate('Quel relais pour chaque élément ?', [('Outil au sol','Préservation sur place et instructions des autorités'),('Images du site','Personnes habilitées selon la procédure'),('Déclarations des employés','Source et coordonnées selon le cadre prévu'),('Débris dans le passage','Protection du périmètre et signalement')], 'Préserver ne signifie pas collecter soi-même tout ce qui pourrait servir.'),
     choice('Quelle réponse donner au responsable ?', 'Laisser l’outil en place, protéger la zone et transmettre sa position aux intervenants.', ['Le prendre avec un chiffon pour éviter les traces.', 'Le remettre à un employé qui le reconnaît.'], 'Même avec un chiffon, une manipulation peut modifier des éléments utiles et exposer à un danger.'),
     sequence('Organisez la découverte.', ['Observer sans entrer inutilement dans la zone', 'Protéger les personnes et limiter les accès', 'Alerter et décrire l’état des lieux', 'Transmettre les modifications éventuelles et suivre les instructions'], 'Une intervention de secours prioritaire doit être expliquée, pas dissimulée pour donner l’impression de lieux intacts.'),
     choice('Un employé a déjà déplacé un débris avant votre arrivée. Que noter ?', 'Le déplacement déclaré, son auteur et les précisions disponibles, en distinguant ce que vous avez vu.', ['Remettre le débris au hasard pour reconstituer.', 'Omettre le déplacement pour simplifier.'], 'La transparence sur une modification est plus utile qu’une reconstitution non fiable.')])

dossier('14-06', 'Remettre un dossier factuel à la police',
    "Une remise d’informations efficace distingue faits, sources, actions et pièces. L’agent doit pouvoir dire ce qu’il a personnellement observé et ce qu’un autre lui a rapporté. Un dossier volumineux mais mélangé peut faire perdre les éléments prioritaires.\n\nLa transmission aux autorités suit le cadre applicable et les canaux prévus, notamment pour les images et données personnelles. L’agent ne fait pas circuler librement des copies ni ne promet une preuve qu’il n’a pas vérifiée. Conservez une trace du destinataire, du moment et des éléments remis selon la procédure.",
    [('Notes du témoin agent', 'À 12 h 03, l’agent voit une personne franchir une porte endommagée avec un carton. Il ne connaît pas le contenu du carton. Il appelle le PC à 12 h 04.'),
     ('Autres éléments', 'Une salariée affirme que du matériel manque, sans inventaire terminé. Des images sont disponibles auprès du gestionnaire habilité. Le responsable a fermé l’accès à 12 h 08.'),
     ('Arrivée des policiers', 'Les policiers demandent un exposé bref, les témoins et les éléments disponibles. L’agent a les heures de ses actions et le contact du gestionnaire des images.')],
    [classify('Attribuez les informations.', ['Observation de l’agent', 'Déclaration ou vérification en attente', 'Action réalisée'], [('Sortie avec un carton',0),('Matériel manquant selon la salariée',1),('Appel au PC à 12 h 04',2),('Contenu exact du carton',1)], 'Le contenu inconnu ne doit pas être remplacé par le matériel supposé manquant.'),
     associate('Reliez les éléments au bon interlocuteur.', [('Geste observé à la porte','Agent témoin'),('Inventaire du matériel','Responsable et salariée concernés'),('Images','Gestionnaire habilité'),('Fermeture de l’accès à 12 h 08','Responsable ayant réalisé la mesure')], 'Identifier la source permet aux autorités de poursuivre les vérifications sans confusion.'),
     choice('Quel exposé initial convient ?', 'Décrire le franchissement, le carton, l’heure et l’alerte, puis distinguer le manque signalé mais non inventorié.', ['Affirmer que le carton contenait tout le matériel manquant.', 'Donner seulement les noms des personnes présentes.'], 'L’exposé relie les faits utiles sans combler les lacunes.'),
     sequence('Préparez la remise.', ['Présenter les faits personnels et la chronologie', 'Identifier les témoins et informations rapportées', 'Indiquer les pièces disponibles et leurs détenteurs', 'Tracer le relais selon la procédure'], 'La transmission doit permettre de retrouver les éléments originaux et leurs sources.'),
     choice('Un policier demande les images. Quelle suite dans le rôle de l’agent ?', 'Mettre en relation avec le gestionnaire habilité et appliquer la procédure de demande et de remise.', ['Envoyer une vidéo personnelle à un numéro non vérifié.', 'Refuser toute transmission par principe.'], 'La coopération et la protection des données se réalisent par un circuit authentifié.')])

dossier('14-07', 'Décider avec une information manquante',
    "L’incertitude fait partie de la surveillance. Il faut décider ce qui peut attendre une vérification et ce qui exige une protection immédiate. Une mesure provisoire doit être justifiée, réversible quand c’est possible et accompagnée d’un relais ; elle ne doit pas devenir une sanction faute d’information.\n\nLe raisonnement doit nommer la donnée manquante et expliquer comment l’obtenir. À défaut, l’agent risque de tourner en boucle ou de combler le vide par une supposition. Lorsqu’une nouvelle information arrive, la décision doit être révisée et la modification transmise à ceux qui appliquent la mesure.",
    [('Livraison tardive au dépôt', 'Un camion se présente à 19 h 10. Le nom du transporteur est connu, mais le numéro de livraison n’apparaît pas sur le planning du soir. Le conducteur présente un document dont la date est aujourd’hui.'),
     ('Contraintes', 'Le responsable de quai est joignable par le PC. Une zone d’attente ne bloque ni les secours ni la circulation. Aucun signe de danger immédiat n’est observé.'),
     ('Information ultérieure', 'À 19 h 18, le responsable confirme une modification de planning et autorise uniquement le quai 2. Le conducteur propose d’aller au quai 1, plus proche.')],
    [classify('Quel statut donner aux informations ?', ['Fait disponible', 'Point à vérifier', 'Confirmation limitée'], [('Date du document aujourd’hui',0),('Droit d’accès de cette livraison au planning du soir',1),('Autorisation reçue pour le quai 2',2),('Autorisation supposée pour tous les quais',1)], 'Une confirmation peut être précise et limitée ; elle ne supprime pas les autres règles.'),
     associate('Reliez les besoins aux mesures.', [('Planning incomplet','Vérification par le PC et le responsable'),('Véhicule en attente','Zone sûre prévue'),('Absence de danger immédiat','Vérification sans contrainte punitive'),('Quai 2 confirmé','Orientation vers cette seule zone')], 'Le dispositif provisoire protège le site tout en permettant une résolution concrète.'),
     choice('À 19 h 10, quelle décision est la plus justifiée ?', 'Faire attendre dans la zone prévue et demander la confirmation de la livraison.', ['Accuser le conducteur de fraude.', 'Laisser entrer sur la seule notoriété du transporteur.'], 'Le cas appelle une vérification identifiable, pas une accusation ni un abandon du contrôle.'),
     sequence('Faites évoluer la décision.', ['Identifier l’information manquante', 'Mettre en place l’attente sûre et demander la vérification', 'Recevoir et reformuler la confirmation précise', 'Adapter l’accès et transmettre la décision'], 'La confirmation doit être comprise dans son périmètre exact.'),
     choice('Le quai 1 est plus proche. Peut-on y orienter le camion ?', 'Pas sans nouvelle confirmation, car l’autorisation reçue vise le quai 2.', ['Oui, la proximité suffit.', 'Oui, puisque le transporteur est connu.'], 'La commodité ne remplace pas l’organisation validée du site.')])

dossier('15-01', 'Qui décide dans l’organisation d’un festival ?',
    "Un dispositif événementiel associe des responsabilités distinctes : organisation, sécurité privée, secours, technique et autorités. L’agent doit connaître son responsable direct, le PC, les zones et les circuits d’alerte. Un ordre d’un prestataire ou d’un artiste ne remplace pas une décision de sécurité validée.\n\nLa préparation d’un poste comprend les accès, les flux, les moyens de communication et les solutions de relais. Une modification d’horaire ou de configuration peut changer les risques. L’agent fait remonter l’écart et demande une consigne claire, sans improviser une répartition des secours ou une fermeture de passage.",
    [('Organisation du festival des Quais', 'Le chef de poste coordonne les agents de l’entrée Est. Le PC central relaie les décisions de sécurité. Les secours ont un accès dédié. Le responsable technique gère l’installation de la scène.'),
     ('Changement annoncé', 'Un prestataire veut stationner son camion sur l’accès secours pour décharger plus vite. Un artiste demande d’ouvrir une porte technique au public pour réduire sa file.'),
     ('Moyens', 'La radio fonctionne et le plan des accès est disponible. Une aire de déchargement alternative existe, à faire confirmer par la coordination. L’agent ne peut pas modifier seul le dispositif public.')],
    [classify('Quelles demandes exigent une validation du dispositif ?', ['Écart à faire arbitrer', 'Action prévue au poste'], [('Camion sur l’accès secours',0),('Ouverture d’une porte technique au public',0),('Appel au chef de poste',1),('Vérification du plan des accès',1)], 'Le statut de l’interlocuteur ne lui donne pas automatiquement autorité sur le dispositif de sécurité.'),
     associate('Reliez les rôles.', [('Chef de poste','Coordination immédiate des agents'),('PC central','Relais des décisions et alertes'),('Responsable technique','Organisation de l’installation'),('Secours','Prise en charge et accès dédié')], 'Connaître les rôles évite les ordres contradictoires et les retards de transmission.'),
     choice('Que répondre au prestataire ?', 'Maintenir l’accès secours libre et demander la confirmation de l’aire alternative.', ['Accepter pour quelques minutes sans prévenir.', 'Lui demander de choisir lui-même une autre issue publique.'], 'Une courte obstruction peut suffire à empêcher une intervention urgente.'),
     sequence('Préparez la prise de poste événementielle.', ['Identifier responsables, zones et accès', 'Vérifier moyens de communication et consignes', 'Faire clarifier les modifications annoncées', 'Confirmer le relais et les mesures applicables au poste'], 'La préparation doit porter sur la configuration du jour, pas seulement sur l’édition précédente.'),
     choice('L’artiste insiste pour ouvrir la porte technique. Que faire ?', 'Saisir le chef de poste ou le PC et attendre une décision compatible avec le dispositif.', ['Obéir parce qu’il est l’invité principal.', 'Fermer toutes les entrées en réaction.'], 'L’arbitrage doit considérer les flux, les secours et l’organisation globale.')])

dossier('15-02', 'Une accréditation ne donne pas tous les accès',
    "Une accréditation associe une personne, des zones, une période et parfois des conditions d’accompagnement. Le contrôle doit vérifier ces éléments, pas seulement la couleur d’un badge. Un badge peut être expiré, prêté ou limité à un secteur.\n\nLe traitement d’un écart doit préserver les flux : placer la demande dans le circuit de vérification prévu sans humilier la personne ni abandonner le contrôle. Les fonctions d’artiste, de technicien ou d’invité ne permettent pas de déduire toutes les autorisations. Une confirmation orale doit venir du bon interlocuteur et préciser sa portée.",
    [('Table des accès du congrès', 'Badge technique T : zone de montage de 06 h à 10 h. Badge intervenant I : loges et salle de conférence. Zone PC : autorisation nominative spécifique. Les invités utilisent l’entrée publique.'),
     ('Arrivées à 11 h', 'Un technicien présente un badge T et demande le PC. Une intervenante présente I et demande sa loge. Un invité dit être ami du directeur mais n’a pas de confirmation d’accès technique.'),
     ('Vérification disponible', 'Le service accréditation peut confirmer les modifications. Un point latéral permet de traiter les écarts sans bloquer le passage. Le PC reste une zone réservée.')],
    [classify('Selon le seul tableau, quel accès est établi ?', ['Compatible avec le badge présenté', 'Confirmation supplémentaire nécessaire'], [('Intervenante I vers sa loge',0),('Technicien T au PC à 11 h',1),('Invité vers une zone technique sur relation personnelle',1),('Badge I vers le PC',1)], 'Zone, horaire et titulaire se vérifient séparément. Une couleur ne constitue pas un droit général.'),
     associate('Reliez chaque contrôle à son objet.', [('Identité du porteur','Concordance avec le titulaire'),('Zone demandée','Périmètre autorisé'),('Heure de passage','Validité temporelle'),('Service accréditation','Confirmation des changements')], 'Un contrôle complet reste explicable et évite les décisions fondées sur la notoriété.'),
     choice('Que faire pour le technicien ?', 'Le diriger vers la vérification latérale et faire confirmer son besoin et son autorisation.', ['Le laisser entrer au PC avec son badge technique.', 'Le déclarer fraudeur parce que son créneau est dépassé.'], 'L’écart appelle une vérification ; il ne prouve pas une intention frauduleuse.'),
     sequence('Traitez un accès exceptionnel.', ['Identifier personne, zone et horaire demandés', 'Comparer au titre présenté', 'Obtenir une confirmation du service compétent si nécessaire', 'Appliquer et tracer l’autorisation précise'], 'L’exception doit rester identifiable, sans ouvrir d’autres zones par extension.'),
     choice('L’accréditation confirme seulement la zone de montage jusqu’à midi. Le PC devient-il accessible ?', 'Non, le périmètre confirmé reste la zone de montage.', ['Oui, la prolongation couvre tout le site.', 'Oui, si le technicien dit avoir une urgence.'], 'Une prolongation de temps n’est pas une extension de zone.')])

dossier('15-03', 'Une file d’attente qui coupe un passage',
    "Une file doit être observée comme un flux dans un espace, pas seulement comme un nombre de personnes. Sa direction, sa vitesse, les obstacles, les croisements et les voies de secours influencent le risque. Une file calme peut déjà créer un danger si elle coupe une circulation essentielle.\n\nL’agent signale les changements et applique les mesures validées : information, orientation, régulation ou suspension d’un flux. Déplacer une barrière sans analyser l’aval peut reporter le problème ailleurs. Le public a besoin d’instructions simples, cohérentes et données assez tôt pour éviter les mouvements brusques.",
    [('Plan de l’entrée d’une foire', 'La file doit rester dans un couloir balisé. Un passage transversal dessert les secours et les sanitaires. Une zone tampon est prévue en amont sous coordination du PC.'),
     ('Affluence à 14 h', 'La file déborde sur le passage transversal. Les personnes ne se poussent pas encore, mais des familles s’arrêtent au croisement. Un contrôle plus lent s’est créé à l’un des guichets.'),
     ('Moyens', 'Le chef de poste peut réguler l’arrivée vers le couloir et renforcer l’information. L’ouverture d’un second contrôle nécessite une décision et du personnel disponible.')],
    [classify('Quels signes sont utiles à signaler ?', ['Fait opérationnel', 'Conclusion non établie'], [('Débordement sur le passage transversal',0),('Violence générale de la foule',1),('Ralentissement d’un guichet',0),('Arrêts de familles au croisement',0)], 'Le danger peut venir de la configuration avant tout comportement violent.'),
     associate('Reliez le constat à l’enjeu.', [('Passage transversal occupé','Accès et circulation à préserver'),('Guichet ralenti','Cause possible d’accumulation'),('Zone tampon','Possibilité de régulation coordonnée'),('Second contrôle','Besoin de décision et de personnel')], 'Il faut traiter la cause et l’aval, pas seulement pousser la file plus loin.'),
     choice('Quelle alerte est la plus utile au PC ?', 'Décrire le débordement, le passage touché, le ralentissement et demander la régulation prévue.', ['Dire seulement « il y a beaucoup de monde ».', 'Annoncer une panique sans signe correspondant.'], 'Les détails permettent au PC de choisir une mesure adaptée.'),
     sequence('Réagissez au débordement.', ['Observer le croisement et les voies à préserver', 'Alerter le chef de poste avec les faits', 'Mettre en œuvre la régulation et l’information confirmées', 'Surveiller l’effet en amont et en aval'], 'Une mesure doit être évaluée après sa mise en place pour éviter de déplacer le risque.'),
     choice('La file raccourcit mais bloque maintenant la sortie des sanitaires. Est-ce résolu ?', 'Non, il faut signaler le nouveau blocage et adapter la régulation.', ['Oui, le nombre de personnes a diminué.', 'Oui, tant que le premier passage est libre.'], 'L’objectif est un fonctionnement sûr de l’ensemble des cheminements, pas un indicateur isolé.')])

dossier('15-04', 'Repérer une pression dangereuse dans le public',
    "Une foule dense peut créer des contraintes physiques sans intention violente. Observez la capacité des personnes à choisir leur mouvement, les vagues de déplacement, les appels à l’aide, les chutes et les points de compression. Le bruit d’un concert ne suffit pas à juger la situation rassurante.\n\nL’agent doit alerter tôt avec une localisation précise et appliquer la coordination prévue. Ne créez pas un mouvement contraire ou une ouverture improvisée vers une zone incapable d’absorber le flux. Les mesures impliquant les accès, l’animation ou l’organisation générale relèvent du PC et des responsables compétents.",
    [('Secteur devant une scène', 'Un groupe se densifie près d’une barrière. Des personnes indiquent ne plus pouvoir reculer librement. Un mouvement ondulatoire apparaît et un spectateur appelle à l’aide.'),
     ('Configuration', 'Un passage latéral est réservé aux équipes et ne débouche pas sur une zone publique dimensionnée. Le PC dispose du plan et peut coordonner les secours et les mesures de régulation.'),
     ('Réaction proposée', 'Un bénévole veut ouvrir immédiatement la barrière latérale et crier à tout le monde de courir. L’agent dispose d’une radio et connaît le repère de secteur S2.')],
    [classify('Quels éléments indiquent un besoin d’alerte immédiate ?', ['Signe préoccupant décrit', 'N’est pas une preuve de sécurité'], [('Impossibilité de reculer librement',0),('Mouvement ondulatoire',0),('Musique qui continue normalement',1),('Appel à l’aide',0)], 'Le risque de pression ne dépend pas d’une intention agressive ni de l’arrêt du spectacle.'),
     associate('Reliez les informations aux décisions.', [('Secteur S2','Localisation du risque'),('Personnes ne pouvant plus bouger librement','Nature de la contrainte'),('Passage latéral inadapté','Limite d’une ouverture improvisée'),('PC et secours','Coordination des mesures')], 'Une ouverture peut créer un transfert dangereux si l’aval n’est pas adapté.'),
     choice('Quelle action engager ?', 'Alerter immédiatement le PC sur S2 et appliquer les mesures coordonnées de protection et de secours.', ['Ouvrir n’importe quel passage et demander de courir.', 'Attendre une chute multiple avant de signaler.'], 'L’alerte précoce permet d’agir avant l’aggravation ; une injonction à courir peut accentuer les mouvements.'),
     sequence('Structurez le message urgent.', ['Localiser le secteur concerné', 'Décrire la contrainte, les mouvements et l’appel à l’aide', 'Demander la coordination et le secours nécessaires', 'Confirmer les consignes reçues et transmettre l’évolution'], 'La précision aide à mobiliser le bon dispositif sans créer de consignes concurrentes.'),
     choice('Le mouvement semble diminuer pendant quelques secondes. Peut-on annuler l’alerte sans autre contrôle ?', 'Non, transmettre l’évolution et maintenir l’évaluation coordonnée.', ['Oui, quelques secondes calmes suffisent.', 'Oui, si personne ne crie plus.'], 'Une amélioration momentanée ne confirme pas que les personnes ont retrouvé un espace et une mobilité sûrs.')])

dossier('15-05', 'Choisir un cheminement de mise en sécurité cohérent',
    "La mise en sécurité dépend de la localisation du danger et de l’état des cheminements. Évacuer vers un secteur menacé peut aggraver la situation. La consigne doit donc être adaptée au scénario réel et aux instructions du PC et des autorités, sans automatisme fondé sur l’habitude.\n\nLes personnes ont besoin d’un message clair, d’une direction praticable et d’un accompagnement adapté aux besoins d’accessibilité. Ne donnez pas plusieurs directions contradictoires. Les voies restent surveillées et les changements sont transmis. Une réintégration ou un retour ne se décide pas sur la seule disparition apparente du signe initial.",
    [('Plan du salon', 'Les sorties Nord et Sud conduisent à deux espaces distincts. Un cheminement accessible rejoint la sortie Sud. Le PC peut donner une consigne de mise en sécurité par secteur.'),
     ('Incident extérieur', 'Un danger est signalé dans la zone extérieure Nord. Le PC confirme de ne pas y orienter le public et valide le cheminement Sud pour le secteur de l’agent.'),
     ('Public et équipe', 'Un collègue oriente encore vers le Nord par habitude. Une personne a besoin du cheminement accessible. Des visiteurs souhaitent retourner à leur stand prendre des affaires.')],
    [classify('Quels choix respectent la situation confirmée ?', ['Choix adapté', 'Choix à corriger'], [('Orientation du secteur vers le Sud',0),('Orientation vers le Nord par habitude',1),('Utilisation du cheminement accessible Sud',0),('Retour aux stands pour les affaires personnelles',1)], 'La direction dépend du danger localisé et de la consigne actuelle, pas de la sortie habituelle.'),
     associate('Reliez les besoins aux mesures.', [('Consigne contradictoire du collègue','Correction et confirmation immédiates'),('Besoin d’accessibilité','Accompagnement sur le cheminement prévu'),('Affaires laissées au stand','Éviter les retours en zone quittée'),('Évolution du danger','Mise à jour par le PC')], 'La cohérence des messages et l’accessibilité font partie de la sécurité du flux.'),
     choice('Quelle priorité de communication avec le collègue ?', 'Lui transmettre la consigne Sud confirmée et vérifier qu’il cesse d’orienter vers le Nord.', ['Le laisser gérer son groupe avec son habitude.', 'Crier deux directions au public pour qu’il choisisse.'], 'Deux instructions opposées peuvent créer des croisements et exposer des personnes.'),
     sequence('Appliquez la mise en sécurité du secteur.', ['Confirmer danger et cheminement validé', 'Aligner les consignes de l’équipe', 'Orienter le public avec les aides nécessaires', 'Rendre compte et attendre les instructions de suite'], 'L’accompagnement se poursuit jusqu’au relais prévu ; il ne s’arrête pas au franchissement d’une porte.'),
     choice('Le danger Nord n’est plus visible. Peut-on autoriser le retour ?', 'Pas sans la confirmation prévue par le PC ou l’autorité compétente.', ['Oui, une absence de signe visible suffit.', 'Oui, pour les exposants uniquement.'], 'L’agent peut transmettre son observation, mais ne transforme pas cette observation en autorisation générale.')])

dossier('15-06', 'Accueillir secours, prestataires et médias',
    "Les intervenants n’ont pas tous le même rôle ni le même circuit d’accès. L’accueil des secours doit être rapide et orienté vers le lieu utile, conformément au dispositif. Un prestataire technique ou un média suit les règles d’accréditation propres à sa mission.\n\nLe contrôle ne doit pas retarder une intervention urgente par des formalités ordinaires inadaptées. Il doit cependant s’appuyer sur les contacts et confirmations prévus, sans se fier à une simple déclaration d’autorité. L’agent prépare le trajet, identifie le relais et transmet les dangers connus. Il ne laisse pas un groupe suivre les secours dans une zone réservée.",
    [('Dispositif du tournoi', 'L’accès S est réservé aux secours et fait l’objet d’un accueil par un agent désigné. Les prestataires passent par T avec accréditation. Les médias sont orientés vers M. Le PC coordonne les arrivées urgentes.'),
     ('Arrivées simultanées', 'Le PC annonce une équipe de secours pour une victime au secteur 4. Un technicien veut la suivre pour gagner du temps. Un photographe demande à entrer par S pour couvrir l’incident.'),
     ('État des lieux', 'Le chemin vers le secteur 4 est libre mais traverse un flux public à réguler. Le responsable de secteur attend les secours. Les médias n’ont pas d’autorisation pour la zone de prise en charge.')],
    [classify('Quel circuit correspond au dispositif ?', ['Circuit secours S', 'Circuit prestataire T', 'Circuit médias M'], [('Équipe de secours annoncée par le PC',0),('Technicien souhaitant un raccourci',1),('Photographe sans autorisation de zone de soins',2),('Autre prestataire technique accrédité',1)], 'L’urgence d’un intervenant ne crée pas un accès collectif pour ceux qui le suivent.'),
     associate('Préparez le relais des secours.', [('Secteur 4','Destination de l’intervention'),('Responsable de secteur','Interlocuteur sur place'),('Flux public traversé','Point à réguler'),('PC','Coordination et confirmation de l’arrivée')], 'Un accueil efficace relie accès, trajet et destinataire sans exposer le public.'),
     choice('Quelle réponse au technicien ?', 'L’orienter vers T et son circuit de vérification, sans le laisser suivre l’équipe de secours.', ['Le laisser passer pour ne pas ralentir les secours.', 'L’intégrer à l’équipe de secours.'], 'Le maintien des circuits évite une intrusion et laisse les secours accomplir leur mission.'),
     sequence('Accueillez l’équipe annoncée.', ['Confirmer l’arrivée avec le PC dans le dispositif prévu', 'Préparer le passage sûr et le relais de secteur', 'Orienter rapidement vers la victime et signaler les dangers connus', 'Informer le PC de la prise en charge du guidage'], 'Les formalités ordinaires ne doivent pas se substituer au dispositif d’urgence prévu.'),
     choice('Le photographe montre une carte de presse. Cela lui donne-t-il accès à la zone de prise en charge ?', 'Non, il faut l’autorisation correspondant à la zone et aux règles de l’événement.', ['Oui, toute carte de presse ouvre toutes les zones.', 'Oui, s’il reste derrière les secours.'], 'La qualité professionnelle ne supprime pas les restrictions justifiées de sécurité et de protection des personnes.')])

dossier('15-07', 'Un billet refusé sans accusation immédiate',
    "Un refus du lecteur peut provenir d’un billet déjà utilisé, d’une mauvaise date, d’une panne, d’un défaut de lecture ou d’une autre anomalie. Le message affiché doit être comparé aux informations du billet et à l’état du système. L’agent ne conclut pas à une fraude sur un résultat technique isolé.\n\nLe traitement d’un billet litigieux doit sortir du flux principal sans isoler dangereusement ni humilier le visiteur. Le service de billetterie vérifie les données auxquelles il est habilité et confirme la suite. Une même règle doit être appliquée à tous ; la notoriété, l’agacement ou la pression de la file ne remplacent pas cette vérification.",
    [('Lecteur de l’entrée Ouest', 'Le lecteur affiche « code non reconnu » pour trois visiteurs successifs. Un quatrième billet est accepté. Le réseau est signalé instable par le PC.'),
     ('Billet présenté', 'Une visiteuse possède un billet daté du jour et un courriel de confirmation. Le code sur l’écran est partiellement masqué par une fissure. Elle accepte une vérification auprès de la billetterie.'),
     ('Organisation', 'Un guichet de résolution se trouve à côté du contrôle. La file doit rester libre. Le service billetterie peut vérifier la référence sans que l’agent demande l’accès complet à la messagerie de la visiteuse.')],
    [classify('Quels éléments orientent la vérification ?', ['Fait utile', 'Conclusion prématurée'], [('Réseau signalé instable',0),('Fraude certaine de la visiteuse',1),('Code partiellement masqué',0),('Plusieurs refus successifs',0)], 'Les difficultés techniques sont compatibles avec plusieurs causes ; elles ne permettent pas une accusation immédiate.'),
     associate('Reliez les éléments à leur traitement.', [('Date et référence du billet','Vérification billetterie'),('Écran fissuré','Autre moyen de lecture prévu'),('Réseau instable','Signalement technique au PC'),('File principale','Orientation vers le guichet latéral')], 'On résout le problème tout en maintenant un flux sûr et en limitant les données consultées.'),
     choice('Quelle formulation utiliser ?', '« Le code n’est pas reconnu ; la billetterie va vérifier votre référence à ce guichet. »', ['« Votre billet est faux. »', '« Donnez-moi l’accès à toute votre messagerie. »'], 'La première phrase décrit le résultat technique et propose une action sans accusation ni accès excessif aux données.'),
     sequence('Traitez le billet litigieux.', ['Lire le message exact et vérifier les éléments visibles utiles', 'Expliquer la difficulté sans qualifier une fraude', 'Orienter vers la résolution sans bloquer le flux', 'Appliquer le résultat confirmé par la billetterie'], 'Le contrôle reste cohérent même lorsque la pression de la file augmente.'),
     choice('La billetterie confirme un billet valable. Quelle suite ?', 'Appliquer la procédure d’admission confirmée et actualiser le suivi de l’anomalie technique.', ['Maintenir le refus pour ne pas contredire le lecteur.', 'Laisser ensuite entrer tous les billets refusés.'], 'La confirmation concerne ce billet ; elle n’autorise pas une dérogation générale pour tous les cas suivants.')])
